INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jameingh/dida-clone/tauri2-react-rust', 'tauri2-react-rust', 'jameingh', 'dida-clone', 'community', 'tauri2-react-rust jameingh dida-clone community Tauri2 React Rust是开发AI工具的框架，使用vibe coding工具开发仿滴答清单app Tauri2 React RustはAIエージェント開発フレームワークで、vibe codingツールを使って類似のアプリを開発できます Tauri2 React Rust는 AI 에이전트 개발 프레임워크로, vibe coding 도구를 사용하여 유사한 앱을 개발할 수 있습니다 tauri2-react-rust es una herramienta de AI que permite a los desarrolladores crear aplicaciones con tecnologías como React y Rust tauri2-react-rust est un outil IA qui permet aux développeurs de créer des applications avec des technologies comme React et Rust tauri2-react-rust ist ein KI-Tool, das es Entwicklern ermöglicht, Anwendungen mit Technologien wie React und Rust zu erstellen Tauri2 React Rust é uma combinação poderosa para desenvolvimento de aplicativos, com integração de ferramentas de IA para melhorar a produtividade Tauri2 React Rust - это мощная комбинация для разработки приложений, с интеграцией ИИ Агентов для повышения производительности Tauri2 React Rust هو مزيج قوي لتنمية التطبيقات، مع دمج أدوات الذكاء الاصطناعي لتحسين الإنتاجية 使用vibe coding工具写仿滴答清单app，体验各种AI工具的能力，同时在这个过程中积累AI工具使用的技巧 Tauri2 React Rust AI工具开发 React开发 Rust开发 vibe coding工具 AI工具集成 如何使用Tauri2 Tauri2教程 React和Rust开发 使用vibe coding工具写仿滴答清单app，体验各种AI工具的能力，同时在这个过程中积累AI工具使用的技巧');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('StuartF303/vandaemon/kicad', 'community', 'StuartF303', 'vandaemon', 'StuartF303/vandaemon', 'kicad', 0, 0, 31, '2026-03-04T13:07:01.839Z', '2026-03-04T14:46:49.437Z', '3db1fb26084ff23ae94bf43606557f6838adfb9dd684b450dc4f7ad2e4c0934e', '{"id":"StuartF303/vandaemon/kicad","name":"kicad","description":{"zh":"KiCad是一款用于ModBus的中央控制系统，使用C#开发，提供智能化管理解决方案","ja":"KiCadはModBus用の中央制御システムで、C#で開発されており、智能化管理ソリューションを提供","ko":"KiCad는 ModBus용 중앙 제어 시스템으로, C#로 개발되어智能化 관리 솔루션을 제공","es":"KiCad es un sistema de control central para camper vans que utiliza ModBus en C#. Ofrece una solución integral para el desarrollo de proyectos de automatización.","fr":"KiCad est un système de contrôle central pour les fourgons aménagés qui utilise ModBus en C#. Il offre une solution complète pour le développement de projets d''automatisation.","de":"KiCad ist ein zentrales Steuersystem für Wohnmobile, das ModBus in C# verwendet. Es bietet eine umfassende Lösung für die Entwicklung von Automatisierungsprojekten.","pt":"O KiCad é uma ferramenta de código aberto para design de PCB que pode ser utilizada para criar um sistema de controle central para vans com ModBus em C#","ru":"KiCad - это открытая инструментальная плата для проектирования PCB, которая может быть использована для создания центрального системы управления для камперов с ModBus на C#","ar":"KiCad هو أداة مفتوحة المصدر لتصميم لوحات الدائرة المطبوعة التي يمكن استخدامها لإنشاء نظام تحكم مركزي للفان مع ModBus في سي شارب","en":"a central camper van control system for ModBus in c# "},"seo":{"title":{"zh":"KiCad AIエージェント - ModBus中央控制系统","ja":"KiCad AIエージェント - ModBus中央制御システム","ko":"KiCad AI 에이전트 - ModBus 중앙 제어 시스템","es":"Herramientas de AI: KiCad para ModBus en C#","fr":"Outils d''IA: KiCad pour ModBus en C#","de":"KI-Agenten: KiCad für ModBus in C#","pt":"Ferramentas de AI: KiCad para Controle de Van com ModBus ...","ru":"ИИ Агенты: KiCad для управления кампером через ModBus на C#","ar":"أدوات الذكاء الاصطناعي: KiCad لنظام تحكم الفان المركزي مع...","en":"kicad"},"description":{"zh":"KiCad是一款用于ModBus的中央控制系统，使用C#开发，提供智能化管理解决方案","ja":"KiCadはModBus用の中央制御システムで、C#で開発されており、智能化管理ソリューションを提供","ko":"KiCad는 ModBus용 중앙 제어 시스템으로, C#로 개발되어智能化 관리 솔루션을 제공","es":"KiCad es un sistema de control central para camper vans que utiliza ModBus en C#. Ofrece una solución integral para el desarrollo de proyectos de automatizac...","fr":"KiCad est un système de contrôle central pour les fourgons aménagés qui utilise ModBus en C#. Il offre une solution complète pour le développement de projets...","de":"KiCad ist ein zentrales Steuersystem für Wohnmobile, das ModBus in C# verwendet. Es bietet eine umfassende Lösung für die Entwicklung von Automatisierungspro...","pt":"O KiCad é uma ferramenta de código aberto para design de PCB que pode ser utilizada para criar um sistema de controle central para vans com ModBus em C#","ru":"KiCad - это открытая инструментальная плата для проектирования PCB, которая может быть использована для создания центрального системы управления для камперов...","ar":"KiCad هو أداة مفتوحة المصدر لتصميم لوحات الدائرة المطبوعة التي يمكن استخدامها لإنشاء نظام تحكم مركزي للفان مع ModBus في سي شارب","en":"a central camper van control system for ModBus in c# "},"definition":{"en":"a central camper van control system for ModBus in c# "},"features":{"zh":["ModBus协议支持","C#开发","智能化管理","中央控制系统","高效管理"],"ja":["ModBusプロトコル対応","C#開発","智能化管理","中央制御システム","効率的な管理"],"ko":["ModBus 프로토콜 지원","C# 개발","智能化 관리","중앙 제어 시스템","효율적인 관리"],"es":["Control centralizado de sistemas ModBus","Desarrollo de proyectos de automatización en C#","Integración con herramientas de AI para una mayor eficiencia","Solución integral para la automatización de procesos","Compatibilidad con diferentes protocolos de comunicación"],"fr":["Contrôle centralisé des systèmes ModBus","Développement de projets d''automatisation en C#","Intégration avec des outils d''IA pour une plus grande efficacité","Solution complète pour l''automatisation des processus","Compatibilité avec différents protocoles de communication"],"de":["Zentrales Steuersystem für ModBus-Systeme","Entwicklung von Automatisierungsprojekten in C#","Integration mit KI-Tools für eine höhere Effizienz","Umfassende Lösung für die Automatisierung von Prozessen","Kompatibilität mit verschiedenen Kommunikationsprotokollen"],"pt":["Desenvolvimento de sistemas de controle central para vans","Integração com ModBus em C#","Design de PCB com KiCad","Implementação de lógica de controle em C#","Monitoramento e controle de dispositivos via ModBus"],"ru":["Разработка центральных систем управления для камперов","Интеграция с ModBus на C#","Проектирование PCB с KiCad","Реализация логики управления на C#","Мониторинг и управление устройствами через ModBus"],"ar":["تطوير أنظمة التحكم المركزي للفان","التكامل مع ModBus في سي شارب","تصميم لوحات الدائرة المطبوعة مع KiCad","تنفيذ 논理 التحكم في سي شارب","مراقبة وتحكم الأجهزة عبر ModBus"]},"keywords":{"zh":["KiCad","ModBus","C#","智能化管理","中央控制系统","如何使用KiCad","KiCad安装","KiCad设置指南"],"ja":["KiCad","ModBus","C#","智能化管理","中央制御システム","KiCadの使い方","KiCadのインストール","KiCadの設定ガイド"],"ko":["KiCad","ModBus","C#","智能化 관리","중앙 제어 시스템","KiCad 사용법","KiCad 설치","KiCad 설정 가이드"],"es":["cómo usar KiCad","qué es ModBus","alternativas a KiCad","KiCad vs otros herramientas de AI","instalación de KiCad","guía de configuración de KiCad","desarrollo de proyectos de automatización en C#"],"fr":["comment utiliser KiCad","qu''est-ce que ModBus","alternatives à KiCad","KiCad vs autres outils d''IA","installation de KiCad","guide de configuration de KiCad","développement de projets d''automatisation en C#"],"de":["wie man KiCad verwendet","was ist ModBus","Alternativen zu KiCad","KiCad vs andere KI-Tools","Installation von KiCad","Konfigurationsanleitung für KiCad","Entwicklung von Automatisierungsprojekten in C#"],"pt":["como usar KiCad","o que é ModBus","alternativas para KiCad","KiCad vs Eagle","instalar KiCad","guias de configuração do KiCad","desenvolvimento de sistemas de controle","integração com ModBus"],"ru":["как использовать KiCad","что такое ModBus","альтернативы KiCad","KiCad vs Eagle","установить KiCad","руководства по настройке KiCad","разработка систем управления","интеграция с ModBus"],"ar":["كيفية استخدام KiCad","ما هو ModBus","بديل KiCad","KiCad مقابل Eagle","تثبيت KiCad","دليل إعداد KiCad","تطوير أنظمة التحكم","التكامل مع ModBus"]}},"owner":"StuartF303","repo":"vandaemon","repoPath":"StuartF303/vandaemon","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.839Z","topics":[],"category":"community","skillMd":{"name":"kicad","description":"|","bodyPreview":"# KiCad Skill\n\nDesigns PCB schematics and layouts for VanDaemon hardware projects, primarily the ESP32-based 8-channel LED dimmer. KiCad 7+ uses S-expression format for all files. The project follows automotive-grade design practices for reliability in vehicle environments.\n\n## Quick Start\n\n### Find Hardware Project Files\n\n```bash\n# Locate KiCad project files\nfind hw/LEDDimmer -name \"*.kicad_*\" -type f\n\n# Current project structure\nhw/LEDDimmer/\n├── led_dimmer_8ch.kicad_sch    # Main schematic\n├─","body":"# KiCad Skill\n\nDesigns PCB schematics and layouts for VanDaemon hardware projects, primarily the ESP32-based 8-channel LED dimmer. KiCad 7+ uses S-expression format for all files. The project follows automotive-grade design practices for reliability in vehicle environments.\n\n## Quick Start\n\n### Find Hardware Project Files\n\n```bash\n# Locate KiCad project files\nfind hw/LEDDimmer -name \"*.kicad_*\" -type f\n\n# Current project structure\nhw/LEDDimmer/\n├── led_dimmer_8ch.kicad_sch    # Main schematic\n├── led_dimmer_8ch.kicad_pcb    # PCB layout (when created)\n└── led_dimmer_8ch.kicad_pro    # Project settings\n```\n\n### Read Schematic Structure\n\n```bash\n# View schematic header and metadata\nhead -50 hw/LEDDimmer/led_dimmer_8ch.kicad_sch\n\n# Find all component references\ngrep -E \"^\\s+\\(property \\\"Reference\\\"\" hw/LEDDimmer/led_dimmer_8ch.kicad_sch\n```\n\n## Key Concepts\n\n| Concept | Format | Example |\n|---------|--------|---------|\n| Comments | `#` prefix only | `# Power section` |\n| Component reference | `(property \"Reference\" \"R1\")` | Resistor R1 |\n| Pin connection | `(wire (pts ...))` | Net connection |\n| Symbol instance | `(symbol (lib_id \"...\")` | Component placement |\n| Net label | `(label \"VCC\" ...)` | Named net |\n\n## WARNING: Comment Syntax\n\n**KiCad does NOT support semicolon comments.** Use `#` for comments in KiCad files.\n\n```kicad\n# GOOD - Hash comments work\n# Power regulation section\n\n; BAD - Semicolons are NOT comments, they become part of the data\n```\n\n## Common Patterns\n\n### Adding a Component\n\n```kicad\n(symbol (lib_id \"Device:R\")\n  (at 100 50 0)\n  (unit 1)\n  (property \"Reference\" \"R1\" (at 100 45 0))\n  (property \"Value\" \"10k\" (at 100 55 0))\n  (property \"Footprint\" \"Resistor_SMD:R_0603_1608Metric\" (at 100 50 0))\n)\n```\n\n### Creating a Net Connection\n\n```kicad\n(wire (pts (xy 100 50) (xy 120 50)))\n(label \"PWM_CH0\" (at 110 50 0))\n```\n\n## Design Guidelines\n\n| Parameter | Requirement | Reason |\n|-----------|-------------|--------|\n| Trace width (power) | ≥0.5mm | Handle 2A per channel |\n| Trace width (signal) | ≥0.25mm | Manufacturing tolerance |\n| Via size | 0.8mm/0.4mm | Thermal dissipation |\n| Clearance | ≥0.2mm | Automotive reliability |\n| Copper weight | 2oz | Current handling |\n\n## See Also\n\n- [patterns](references/patterns.md) - Schematic and PCB patterns\n- [workflows](references/workflows.md) - Design and export workflows\n\n## Related Skills\n\n- **platformio** skill - Firmware for ESP32 hardware\n- **docker** skill - Build automation for production"},"lastSynced":"2026-03-04T14:46:49.437Z","agentAnalysis":{"suitability":{"en":"Ideal for Embedded Systems Agents requiring advanced PCB design and layout capabilities with KiCad.","zh":"适用于需要高级PCB设计和布局功能的嵌入式系统代理，特别是使用KiCad。","ja":"KiCadを使用する組み込みシステムエージェント向けに、高度なPCB設計およびレイアウト機能を必要とする場合に最適です。","ko":"KiCad를 사용하는 고급 PCB 설계 및 레이아웃 기능을 필요로 하는 임베디드 시스템 에이전트에 적합합니다.","es":"Ideal para Agentes de Sistemas Embebidos que requieren capacidades de diseño y disposición de PCB avanzadas con KiCad.","fr":"Idéal pour les agents de systèmes embarqués nécessitant des capacités de conception et de disposition de PCB avancées avec KiCad.","de":"Ideal für Embedded-System-Agents, die erweiterte PCB-Design- und Layoutfunktionen mit KiCad benötigen.","pt":"Ideal para Agentes de Sistemas Embarcados que exigem capacidades avançadas de design e layout de PCB com KiCad.","ru":"Идеально подходит для агентов встроенных систем, требующих продвинутых возможностей проектирования и компоновки ПЛИС с помощью KiCad.","ar":"مثالي لعميل نظام متضمّن يتطلب قدرات متقدمة لتصميم وترتيب لوحة الدائرة المطبوعة مع KiCad."},"recommendation":{"en":"Empowers agents to design and layout PCB schematics and layouts for hardware projects, utilizing KiCad''s S-expression format and following automotive-grade design practices for reliability, specifically with ModBus and ESP32-based projects like the 8-channel LED dimmer.","zh":"赋予代理设计和布局PCB原理图和布局的能力，用于硬件项目，利用KiCad的S-expression格式，并遵循汽车级设计实践以确保可靠性，特别是ModBus和ESP32-based项目，如8通道LED调光器。","ja":"エージェントに、ハードウェアプロジェクト用のPCB回路図とレイアウトを設計および配置する能力を与え、KiCadのS式形式を使用し、信頼性のために自動車グレードの設計慣行に従う、特にModBusおよびESP32ベースのプロジェクト、たとえば8チャンネルLEDディマー。","ko":"에이전트에 하드웨어 프로젝트용 PCB 회로도 및 레이아웃을 설계 및 배치할 수 있는 능력을 부여하여 KiCad의 S-표현 형식을 사용하고, 신뢰성을 위해 자동차 급의 설계 관행을 따름, 특히 ModBus 및 ESP32 기반 프로젝트, 예를 들어 8채널 LED 디머.","es":"Habilita a los agentes a diseñar y disponer esquemas y diseños de PCB para proyectos de hardware, utilizando el formato de expresión S de KiCad y siguiendo prácticas de diseño de grado automotriz para la confiabilidad, específicamente con proyectos basados en ModBus y ESP32, como el atenuador de LED de 8 canales.","fr":"Permet aux agents de concevoir et de disposer des schémas et des layouts de PCB pour des projets de matériel, en utilisant le format d''expression S de KiCad et en suivant des pratiques de conception de grade automobile pour la fiabilité, notamment avec des projets basés sur ModBus et ESP32, comme le dimmer LED 8 canaux.","de":"Ermöglich es Agents, PCB-Schemata und -Layouts für Hardware-Projekte zu entwerfen und anzuordnen, indem sie das S-Ausdrucksformat von KiCad verwenden und automotive-Grade-Designpraktiken für Zuverlässigkeit befolgen, insbesondere bei ModBus- und ESP32-basierten Projekten wie dem 8-Kanal-LED-Dimmer.","pt":"Habilita os agentes a projetar e dispor esquemáticos e layouts de PCB para projetos de hardware, utilizando o formato S-expression do KiCad e seguindo práticas de design de grau automotivo para confiabilidade, especificamente com projetos baseados em ModBus e ESP32, como o dimmer de LED de 8 canais.","ru":"Наделяет агентов возможностью проектировать и компоновать схемы и компоновки ПЛИС для аппаратных проектов, используя формат S-выражения KiCad и следуя автомобильным стандартам проектирования для повышения надежности, в частности, с проектами на основе ModBus и ESP32, такими как диммер светодиодов на 8 каналов.","ar":"يمنح الوكلاء القدرة على تصميم وترتيب المخططات والرسومات المحددة للهاردوير باستخدام تنسيق تعبير S من KiCad واتباع ممارسات تصميم من الدرجة السيّارة من أجل الموثوقية، وبشكل خاص مع المشاريع القائمة على ModBus وESP32، مثل مشغل الإضاءة الكهربائية ذي 8 قنوات."},"useCases":{"en":["Designing PCB layouts for vehicle control systems","Generating schematics for ESP32-based hardware projects","Creating reliable automotive-grade PCB designs with KiCad"],"zh":["为车辆控制系统设计PCB布局","为ESP32-based硬件项目生成原理图","使用KiCad创建可靠的汽车级PCB设计"],"ja":["車両制御システム用のPCBレイアウトを設計する","ESP32ベースのハードウェアプロジェクト用の回路図を生成する","KiCadを使用して信頼性の高い自動車グレードPCB設計を作成する"],"ko":["차량 제어 시스템을 위한 PCB 레이아웃 설계","ESP32 기반 하드웨어 프로젝트를 위한 회로도 생성","KiCad를 사용하여 신뢰할 수 있는 자동차 급 PCB 설계 생성"],"es":["Diseñar diseños de PCB para sistemas de control de vehículos","Generar esquemas para proyectos de hardware basados en ESP32","Crear diseños de PCB de grado automotriz confiables con KiCad"],"fr":["Concevoir des layouts de PCB pour des systèmes de contrôle de véhicules","Générer des schémas pour des projets de matériel basés sur ESP32","Créer des conceptions de PCB de grade automobile fiables avec KiCad"],"de":["Entwerfen von PCB-Layouts für Fahrzeugsteuersysteme","Erzeugen von Schemata für ESP32-basierte Hardware-Projekte","Erstellen von zuverlässigen automotive-Grade-PCB-Entwürfen mit KiCad"],"pt":["Projetar layouts de PCB para sistemas de controle de veículos","Gerar esquemáticos para projetos de hardware baseados em ESP32","Criar projetos de PCB de grau automotivo confiáveis com KiCad"],"ru":["Проектировать компоновку ПЛИС для систем управления транспортными средствами","Генерировать схемы для аппаратных проектов на основе ESP32","Создавать надежные автомобильные проекты ПЛИС с помощью KiCad"],"ar":["تصميم مخططات لوحة الدائرة المطبوعة لأنظمة التحكم في المركبات","توليد مخططات لمشاريع هاردوير تعتمد على ESP32","إنشاء تصاميم موثوقة من الدرجة السيّارة للوحة الدائرة المطبوعة باستخدام KiCad"]},"limitations":{"en":["Requires KiCad 7+ for S-expression format compatibility","Limited to automotive-grade design practices and environments"],"zh":["需要KiCad 7+才能兼容S-expression格式","仅限于汽车级设计实践和环境"],"ja":["S式形式の互換性を確保するためにKiCad 7+が必要","自動車グレードの設計慣行および環境に限定される"],"ko":["S-표현 형식 호환성을 보장하기 위해 KiCad 7+가 필요","자동차 급 설계 관행 및 환경으로 제한"],"es":["Requiere KiCad 7+ para la compatibilidad con el formato de expresión S","Limitado a prácticas de diseño y entornos de grado automotriz"],"fr":["Nécessite KiCad 7+ pour la compatibilité avec le format d''expression S","Limité aux pratiques de conception et aux environnements de grade automobile"],"de":["Benötigt KiCad 7+ für die Kompatibilität mit dem S-Ausdrucksformat","Begrenzt auf Designpraktiken und Umgebungen von automotive-Grade"],"pt":["Exige KiCad 7+ para compatibilidade com o formato S-expression","Limitado a práticas de design de grau automotivo e ambientes"],"ru":["Требует KiCad 7+ для совместимости с форматом S-выражения","Ограничен автомобильными стандартами проектирования и средами"],"ar":["يتطلب KiCad 7+ من أجل التوافق مع تنسيق تعبير S","محدود بممارسات تصميم الدرجة السيّارة والبيئات"]},"version":3},"contentHash":"3db1fb26084ff23ae94bf43606557f6838adfb9dd684b450dc4f7ad2e4c0934e","qualityScore":31}');
