INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StuartF303/vandaemon/kicad', 'kicad', 'StuartF303', 'vandaemon', 'community', 'kicad StuartF303 vandaemon community KiCad是一款用于ModBus的中央控制系统，使用C#开发，提供智能化管理解决方案 KiCadはModBus用の中央制御システムで、C#で開発されており、智能化管理ソリューションを提供 KiCad는 ModBus용 중앙 제어 시스템으로, C#로 개발되어智能化 관리 솔루션을 제공 KiCad es un sistema de control central para camper vans que utiliza ModBus en C#. Ofrece una solución integral para el desarrollo de proyectos de automatización. KiCad est un système de contrôle central pour les fourgons aménagés qui utilise ModBus en C#. Il offre une solution complète pour le développement de projets d''automatisation. KiCad ist ein zentrales Steuersystem für Wohnmobile, das ModBus in C# verwendet. Es bietet eine umfassende Lösung für die Entwicklung von Automatisierungsprojekten. O KiCad é uma ferramenta de código aberto para design de PCB que pode ser utilizada para criar um sistema de controle central para vans com ModBus em C# KiCad - это открытая инструментальная плата для проектирования PCB, которая может быть использована для создания центрального системы управления для камперов с ModBus на C# KiCad هو أداة مفتوحة المصدر لتصميم لوحات الدائرة المطبوعة التي يمكن استخدامها لإنشاء نظام تحكم مركزي للفان مع ModBus في سي شارب a central camper van control system for ModBus in c# KiCad ModBus C# 智能化管理 中央控制系统 如何使用KiCad KiCad安装 KiCad设置指南 a central camper van control system for ModBus in c# ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('twentyhq/twenty/syncable-entity-testing', 'community', 'twentyhq', 'twenty', 'twentyhq/twenty', 'syncable-entity-testing', 0, 0, 31, '2026-03-04T13:07:01.843Z', '2026-03-04T14:47:48.180Z', '033fd9fd459b29ee155e28bb9bc4adfe6d389f7394a511e489f3020fe033987d', '{"id":"twentyhq/twenty/syncable-entity-testing","name":"syncable-entity-testing","description":{"zh":"syncable-entity-testing是一个用于构建现代化的Salesforce替代品的工具，依靠社区驱动","ja":"同期可能エンティティテストは、コミュニティ駆動のSalesforceの代替品を構築するためのツールです","ko":"syncable-entity-testing는 커뮤니티 주도형 Salesforce 대체품을 구축하기 위한 도구입니다","es":"Construye una alternativa moderna a Salesforce con pruebas de entidades sincronizables y herramientas de AI, impulsada por la comunidad","fr":"Construire une alternative moderne à Salesforce avec des tests d''entités synchronisables et des outils d''IA, propulsée par la communauté","de":"Erstellen Sie eine moderne Alternative zu Salesforce mit Tests für synchronisierbare Entitäten und KI-Tools, angetrieben von der Community","pt":"Construa uma alternativa moderna ao Salesforce, impulsionada pela comunidade, com testes de entidades sincronizáveis e tecnologias como React e Node.js","ru":"Постройте современную альтернативу Salesforce, основанную на сообществе, с помощью тестирования синхронизируемых сущностей и технологий như React и Node.js","ar":"ابني بديلا حديثا لSalesforce مدعوم من المجتمع، مع اختبار الكيانات القابلة للتزامن وتكنولوجيا مثل React و Node.js","en":"Building a modern alternative to Salesforce, powered by the community."},"seo":{"title":{"zh":"AI智能体同步测试 -syncable-entity-testing","ja":"AIエージェントの同期可能エンティティテスト","ko":"AI 에이전트 동기화 가능 엔티티 테스트 - syncable-entity-testing","es":"Herramientas de AI: Pruebas de Entidades Sincronizables","fr":"Outils d''IA: Tests d''Entités Synchronisables","de":"KI-Tools: Testen von Synchronisierbaren Entitäten","pt":"Ferramen