INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ozahirnyi/movie_finder/connect-to-lightsail-instance', 'connect-to-lightsail-instance', 'ozahirnyi', 'movie_finder', 'community', 'connect-to-lightsail-instance ozahirnyi movie_finder community connect-to-lightsail-instance AI 工具用于简化 Lightsail 实例的管理，实现轻松连接和控制 Lightsail インスタンスの管理を簡素化する connect-to-lightsail-instance AI エージェントは、簡単に接続して制御できます Lightsail 인스턴스 관리를 간소화하는 connect-to-lightsail-instance AI 에이전트는 쉽게 연결하고 제어할 수 있습니다 Conecta a tu instancia de Lightsail con herramientas de IA para una integración sin problemas Connectez votre instance Lightsail avec des outils d''IA pour une intégration sans problème Verbinden Sie Ihre Lightsail-Instanz mit KI-Tools für eine reibungslose Integration Conecte-se ao Lightsail com facilidade usando nossas ferramentas de IAs para desenvolvedores. Aprenda a integrar e otimizar seu workflow Подключитесь к Lightsail легко с помощью наших ИИ Агентов для разработчиков. Узнайте, как интегрировать и оптимизировать свой рабочий процесс اتصل بخدمة Lightsail بسهولة باستخدام أدواتنا الذكية للطورين. تعلم كيفية دمج وتحسين تدفق العمل الخاص بك App for saving and searching movies 如何使用 connect-to-lightsail-instance Lightsail 实例管理工具 connect-to-lightsail-instance 教程 Lightsail 实例连接 AI 工具安装 Lightsail 实例设置指南 App for saving and searching movies');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('congwa/embedease-ai/image-compress', 'community', 'congwa', 'embedease-ai', 'congwa/embedease-ai', 'image-compress', 0, 0, 31, '2026-03-04T13:07:01.853Z', '2026-03-04T14:50:32.958Z', 'a82a3ca886de046173759b2652884690cc4c48a7ba2b7eab38c2aa7376cddef1', '{"id":"congwa/embedease-ai/image-compress","name":"image-compress","description":{"zh":"一款开箱即用的AI智能图像压缩系统，使用人工智能技术实现快速高效的图片压缩","ja":"オープンソースのAIエージェントによる画像圧縮システムで、人工知能技術を活用して迅速かつ効率的に画像を圧縮します","ko":"오픈소스의 AI 인텔리전트 이미지 압축 시스템으로 인공지능 기술을 활용하여 빠르고 효율적인 이미지 압축을 구현합니다","es":"La herramienta de compresión de imágenes AI es una solución para optimizar imágenes","fr":"L''outil de compression d''images IA est une solution pour optimiser les images","de":"Das AI-Bildkomprimierungstool ist eine Lösung zur Optimierung von Bildern","pt":"A ferramenta de compressão de imagem AI é uma solução inteligente para reduzir o tamanho de imagens sem perder qualidade. Ela é ideal para desenvolvedores que buscam melhorar a velocidade de carregamento de suas aplicações.","ru":"ИИ Агент для сжатия изображений - это умное решение для снижения размера изображений без потери качества. Он идеален для разработчиков, которые хотят улучшить скорость загрузки своих приложений.","ar":"أداة ضغط الصور الذكية هي حل ذكي لتقليص حجم الصور دون فقدان الجودة. وهي مثالية للمطورين الذين يبحثون عن تحسين سرعة تحميل تطبيقاتهم.","en":"一款开箱即用的 AI 智能客服系统，人工客服，客户转化"},"seo":{"title":{"zh":"AI智能图像压缩工具","ja":"AIエージェントによる画像圧縮ツール","ko":"AI 인텔리전트 이미지 압축 도구","es":"Herramienta de compresión de imágenes AI","fr":"Outil de compression d''images IA","de":"AI-Bildkomprimierungstool","pt":"Ferramenta de compressão de imagem AI","ru":"ИИ Агент для сжатия изображений","ar":"أداة ضغط الصور الذكية","en":"image-compress"},"description":{"zh":"一款开箱即用的AI智能图像压缩系统，使用人工智能技术实现快速高效的图片压缩","ja":"オープンソースのAIエージェントによる画像圧縮システムで、人工知能技術を活用して迅速かつ効率的に画像を圧縮します","ko":"오픈소스의 AI 인텔리전트 이미지 압축 시스템으로 인공지능 기술을 활용하여 빠르고 효율적인 이미지 압축을 구현합니다","es":"La herramienta de compresión de imágenes AI es una solución para optimizar imágenes","fr":"L''outil de compression d''images IA est une solution pour optimiser les images","de":"Das AI-Bildkomprimierungstool ist eine Lösung zur Optimierung von Bildern","pt":"A ferramenta de compressão de imagem AI é uma solução inteligente para reduzir o tamanho de imagens sem perder qualidade. Ela é ideal para desenvolvedores qu...","ru":"ИИ Агент для сжатия изображений - это умное решение для снижения размера изображений без потери качества. Он идеален для разработчиков, которые хотят улучшит...","ar":"أداة ضغط الصور الذكية هي حل ذكي لتقليص حجم الصور دون فقدان الجودة. وهي مثالية للمطورين الذين يبحثون عن تحسين سرعة تحميل تطبيقاتهم.","en":"一款开箱即用的 AI 智能客服系统，人工客服，客户转化"},"definition":{"en":"一款开箱即用的 AI 智能客服系统，人工客服，客户转化"},"features":{"zh":["使用人工智能技术实现快速高效的图片压缩","支持多种图片格式","可调整压缩质量","简单易用的API接口","支持批量压缩"],"ja":["人工知能技術を活用して迅速かつ効率的に画像を圧縮","複数の画像形式をサポート","圧縮品質を調整可能","シンプルなAPIインターフェース","バッチ圧縮をサポート"],"ko":["인공지능 기술을 활용하여 빠르고 효율적인 이미지 압축","여러 가지 이미지 형식을 지원","압축 품질을 조정할 수 있음","간단한 API 인터페이스","일괄 압축을 지원"],"es":["Compresión de imágenes sin pérdida de calidad","Optimización para web y dispositivos móviles","Integración con herramientas de desarrollo","Soporte para múltiples formatos de imagen","Interfaz de usuario intuitiva"],"fr":["Compression d''images sans perte de qualité","Optimisation pour le web et les appareils mobiles","Intégration avec les outils de développement","Prise en charge de plusieurs formats d''image","Interface utilisateur intuitive"],"de":["Bildkomprimierung ohne Qualitätsverlust","Optimierung für Web und mobile Geräte","Integration mit Entwicklungstools","Unterstützung für mehrere Bildformate","Benutzerfreundliche Oberfläche"],"pt":["Redução de tamanho de imagem sem perda de qualidade","Melhoria da velocidade de carregamento de aplicações","Compatibilidade com várias extensões de imagem","Fácil integração com projetos existentes","Suporte a múltiplos formatos de imagem"],"ru":["Снижение размера изображений без потери качества","Улучшение скорости загрузки приложений","Возможность работы с различными расширениями изображений","Легкая интеграция с существующими проектами","Поддержка нескольких форматов изображений"],"ar":["تقليل حجم الصور دون فقدان الجودة","تحسين سرعة تحميل التطبيقات","دعم لعدة امتدادات للصور","تكامل سهل مع المشاريع الحالية","دعم لعدة صيغ للصور"]},"keywords":{"zh":["AI智能图像压缩","图片压缩工具","如何使用AI压缩图片","AI图像压缩与传统压缩的区别","AI智能图像压缩工具安装","AI图像压缩设置指南"],"ja":["AIエージェントによる画像圧縮","画像圧縮ツール","AIを使用して画像を圧縮する方法","AI画像圧縮と伝統的な圧縮の違い","AIエージェントによる画像圧縮ツールのインストール","AI画像圧縮設定ガイド"],"ko":["AI 인텔리전트 이미지 압축","이미지 압축 도구","AI를 사용하여 이미지를 압축하는 방법","AI 이미지 압축과 전통적인 압축의 차이","AI 인텔리전트 이미지 압축 도구 설치","AI 이미지 압축 설정 가이드"],"es":["herramienta de compresión de imágenes","compresión de imágenes sin pérdida de calidad","optimización de imágenes para web","cómo usar la herramienta de compresión de imágenes","alternativas a la herramienta de compresión de imágenes","guía de instalación de la herramienta de compresión de imágenes"],"fr":["outil de compression d''images","compression d''images sans perte de qualité","optimisation d''images pour le web","comment utiliser l''outil de compression d''images","alternatives à l''outil de compression d''images","guide d''installation de l''outil de compression d''images"],"de":["AI-Bildkomprimierungstool","Bildkomprimierung ohne Qualitätsverlust","Optimierung von Bildern für das Web","wie man das AI-Bildkomprimierungstool verwendet","Alternativen zum AI-Bildkomprimierungstool","Installationsanleitung für das AI-Bildkomprimierungstool"],"pt":["como usar ferramenta de compressão de imagem","o que é compressão de imagem AI","ferramenta de compressão de imagem alternative","ferramenta de compressão de imagem vs competitor","instalar ferramenta de compressão de imagem","guia de configuração da ferramenta de compressão de imagem","melhor ferramenta de compressão de imagem para desenvolvedores"],"ru":["как использовать ИИ Агент для сжатия изображений","что такое сжатие изображений ИИ","ИИ Агент для сжатия изображений alternative","ИИ Агент для сжатия изображений vs конкурент","установить ИИ Агент для сжатия изображений","руководство по настройке ИИ Агента для сжатия изображений","лучший ИИ Агент для сжатия изображений для разработчиков"],"ar":["كيفية استخدام أداة ضغط الصور الذكية","ما هي ضغط الصور الذكي","أداة ضغط الصور الذكية بديلة","أداة ضغط الصور الذكية مقابل منافس","تثبيت أداة ضغط الصور الذكية","دليل إعداد أداة ضغط الصور الذكية","أفضل أداة ضغط الصور الذكية للمطورين"]}},"owner":"congwa","repo":"embedease-ai","repoPath":"congwa/embedease-ai","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.853Z","topics":[],"category":"community","skillMd":{"name":"image-compress","description":"图片压缩检查规则。当添加或修改 README 引用的图片时自动触发。检查图片是否超过 100KB，超出则压缩。推荐使用 avif/webp 格式。触发场景：添加新图片到仓库、更新 README 中的截图、发版前检查。","bodyPreview":"# Image Compress\n\nREADME 引用的图片不得超过 **100KB**。\n\n## 检查规则\n\n1. 扫描 README.md 中所有 `![](path)` 引用的图片文件\n2. 检查每个文件大小，超过 100KB 的必须压缩\n3. 推荐格式优先级：**avif > webp > png > jpg**\n\n## 检查命令\n\n```bash\n# 查找 docs/ 和 images/ 下超过 100KB 的图片\nfind docs/ images/ -type f \\( -name \"*.png\" -o -name \"*.jpg\" -o -name \"*.jpeg\" -o -name \"*.webp\" -o -name \"*.avif\" -o -name \"*.gif\" \\) -size +100k\n```\n\n## 压缩方式\n\n### macOS 内置 sips（png/jpg）\n\n```bash\n# 缩小尺寸（保持宽度 1200px 以内）\nsips --resampleWidth 1200 image.png\n\n# 转为 jpg 并降低质量\nsips -s forma","body":"# Image Compress\n\nREADME 引用的图片不得超过 **100KB**。\n\n## 检查规则\n\n1. 扫描 README.md 中所有 `![](path)` 引用的图片文件\n2. 检查每个文件大小，超过 100KB 的必须压缩\n3. 推荐格式优先级：**avif > webp > png > jpg**\n\n## 检查命令\n\n```bash\n# 查找 docs/ 和 images/ 下超过 100KB 的图片\nfind docs/ images/ -type f \\( -name \"*.png\" -o -name \"*.jpg\" -o -name \"*.jpeg\" -o -name \"*.webp\" -o -name \"*.avif\" -o -name \"*.gif\" \\) -size +100k\n```\n\n## 压缩方式\n\n### macOS 内置 sips（png/jpg）\n\n```bash\n# 缩小尺寸（保持宽度 1200px 以内）\nsips --resampleWidth 1200 image.png\n\n# 转为 jpg 并降低质量\nsips -s format jpeg -s formatOptions 80 image.png --out image.jpg\n```\n\n### ffmpeg（推荐，支持 avif/webp）\n\n```bash\n# png → avif（推荐，体积最小）\nffmpeg -i input.png -c:v libaom-av1 -crf 30 -still-picture 1 output.avif\n\n# png → webp\nffmpeg -i input.png -quality 80 output.webp\n\n# 批量转换\nfor f in docs/screenshots/*.png; do\n  ffmpeg -i \"$f\" -c:v libaom-av1 -crf 30 -still-picture 1 \"${f%.png}.avif\"\ndone\n```\n\n### 使用 scripts/check_compress.sh\n\n```bash\nbash .windsurf/skills/image-compress/scripts/check_compress.sh\n```\n\n## 压缩后\n\n1. 更新 README.md 中的图片路径（扩展名可能变化）\n2. 删除旧的大图片文件\n3. 确认所有图片 < 100KB\n"},"lastSynced":"2026-03-04T14:50:32.958Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient image compression capabilities, particularly those utilizing README files with size constraints.","zh":"非常适合需要高效图像压缩能力的AI代理，特别是那些使用具有大小限制的README文件的代理。","ja":"READMEファイルにサイズ制限があるものを使用するエージェント、特に効率的な画像圧縮機能を必要とするAIエージェントに最適です。","ko":"README 파일에 크기 제한이 있는 에이전트를 사용하는 경우 특히 효율적인 이미지 압축 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de compresión de imágenes eficientes, particularmente aquellos que utilizan archivos README con restricciones de tamaño.","fr":"Parfait pour les agents IA ayant besoin de capacités de compression d''images efficaces, en particulier ceux qui utilisent des fichiers README avec des contraintes de taille.","de":"Perfekt für KI-Agents, die effiziente Bildkomprimierungsfunktionen benötigen, insbesondere solche, die README-Dateien mit Größenbeschränkungen verwenden.","pt":"Perfeito para Agentes de IA que necessitam de capacidades de compressão de imagem eficientes, particularmente aqueles que utilizam arquivos README com restrições de tamanho.","ru":"Идеально подходит для агентов ИИ, которым необходимы эффективные возможности сжатия изображений, особенно тех, которые используют файлы README с ограничениями по размеру.","ar":"مثالي لعميل الإي.ai الذي يحتاج إلى قدرات ضغط الصور الفعالة، ولا سيما أولئك الذين يستخدمون ملفات README مع قيود الحجم."},"recommendation":{"en":"Empowers agents to compress images to optimal formats like avif, webp, png, and jpg, ensuring file sizes are under 100KB for seamless integration into documentation, utilizing tools like sips for macOS and leveraging bash commands for automated scanning and compression.","zh":"赋予代理将图像压缩到avif、webp、png和jpg等最佳格式的能力，确保文件大小低于100KB，以便无缝地集成到文档中，使用macOS的sips工具，并利用bash命令进行自动扫描和压缩。","ja":"エージェントがavif、webp、png、jpgなどの最適な形式に画像を圧縮できるようにし、ファイルサイズが100KB未満になることを保証し、macOSのsipsツールやbashコマンドを使用して自動スキャンおよび圧縮を行うことで、ドキュメントへの統合をスムーズに行えるようにします。","ko":"에이전트가 avif, webp, png 및 jpg와 같은 최적의 형식으로 이미지를 압축할 수 있도록 하여 파일 크기가 100KB 미만이 되도록 보장하고 macOS의 sips 도구 및 bash 명령어를 사용하여 자동 스캔 및 압축을 통해 문서에无缝하게 통합할 수 있습니다.","es":"Permite a los agentes comprimir imágenes a formatos óptimos como avif, webp, png y jpg, garantizando que los tamaños de archivo sean inferiores a 100KB para una integración fluida en la documentación, utilizando herramientas como sips para macOS y aprovechando comandos bash para el escaneo y la compresión automatizados.","fr":"Permet aux agents de compresser les images dans des formats optimaux tels que avif, webp, png et jpg, en garantissant que les tailles de fichiers sont inférieures à 100 Ko pour une intégration fluide dans la documentation, en utilisant des outils tels que sips pour macOS et en exploitant des commandes bash pour un balayage et une compression automatisés.","de":"Ermöglicht es den Agents, Bilder in optimale Formate wie avif, webp, png und jpg zu komprimieren, wodurch sichergestellt wird, dass Dateigrößen unter 100KB bleiben, um eine nahtlose Integration in die Dokumentation zu ermöglichen, unter Verwendung von Tools wie sips für macOS und durch die Nutzung von bash-Befehlen für automatisiertes Scannen und Komprimieren.","pt":"Habilita os agentes a comprimir imagens para formatos ótimos como avif, webp, png e jpg, garantindo que os tamanhos de arquivo sejam inferiores a 100KB para integração perfeita na documentação, utilizando ferramentas como sips para macOS e aproveitando comandos bash para varredura e compressão automatizadas.","ru":"Позволяет агентам сжимать изображения до оптимальных форматов, таких как avif, webp, png и jpg, гарантируя, что размеры файлов составляют менее 100 КБ для бесшовной интеграции в документацию, используя инструменты, такие как sips для macOS, и используя команды bash для автоматизированного сканирования и сжатия.","ar":"يمنح الوكلاء القدرة على ضغط الصور إلى تنسيقات مثالية مثل avif و webp و png و jpg، مما يضمن أن أحجام الملفات تكون أقل من 100 كيلوبايت لتكامل مثالي في الوثائق، باستخدام أدوات مثل sips لنظام macOS واستغلال أوامر bash للفحص والضغط التلقائي."},"useCases":{"en":["Compressing README images for size optimization","Automating image format conversion to avif or webp for better compression ratios","Scanning documentation for oversized images to ensure compliance with size limits"],"zh":["为README图像进行大小优化的压缩","自动将图像格式转换为avif或webp以获得更好的压缩比","扫描文档以检查超大图像并确保符合大小限制"],"ja":["README画像のサイズ最適化のための圧縮","自動的に画像形式をavifまたはwebpに変換してより良い圧縮比を実現する","ドキュメントのサイズ制限に違反する大きな画像をスキャンして検出する"],"ko":["README 이미지의 크기 최적화를 위한 압축","автоматически 이미지를 avif 또는 webp 형식으로 변환하여 더好的 압축 비율을 달성","문서의 크기 제한을 위반하는 큰 이미지를 스캔하여検出"],"es":["Comprimir imágenes de README para la optimización del tamaño","Automatizar la conversión de formato de imagen a avif o webp para mejores ratios de compresión","Escanear la documentación en busca de imágenes de tamaño excesivo para garantizar el cumplimiento de los límites de tamaño"],"fr":["Compresser les images de README pour l''optimisation de la taille","Automatiser la conversion de format d''image en avif ou webp pour de meilleurs ratios de compression","Balayer la documentation à la recherche d''images de taille excessive pour garantir le respect des limites de taille"],"de":["Komprimieren von README-Bildern für die Größenoptimierung","Automatisieren der Umwandlung des Bildformates in avif oder webp für bessere Komprimierungsverhältnisse","Durchscannen der Dokumentation nach übergroßen Bildern, um die Einhaltung der Größenbeschränkungen sicherzustellen"],"pt":["Comprimir imagens de README para otimização de tamanho","Automatizar a conversão de formato de imagem para avif ou webp para melhores taxas de compressão","Digitalizar a documentação para imagens de tamanho excessivo para garantir a conformidade com os limites de tamanho"],"ru":["Сжатие изображений README для оптимизации размера","Автоматизация преобразования формата изображений в avif или webp для лучших коэффициентов сжатия","Сканирование документации для изображений слишком большого размера для обеспечения соответствия ограничениям по размеру"],"ar":["ضغط صور ملفات README لتحسين الحجم","توفير تحويل تنسيق الصورة إلى avif أو webp لratios ضغط أفضل","فحص الوثائق للصور كبيرة الحجم لضمان امتثالها للحدود الحجمية"]},"limitations":{"en":["Requires macOS for sips command functionality","Limited to specific image formats (avif, webp, png, jpg, gif)","100KB file size limit for compressed images"],"zh":["需要macOS来使用sips命令功能","仅限特定图像格式（avif、webp、png、jpg、gif）","压缩图像的文件大小限制为100KB"],"ja":["sipsコマンドの機能を使用するにはmacOSが必要","特定の画像形式（avif、webp、png、jpg、gif）のみ対応","圧縮画像のファイルサイズは100KB以下"],"ko":["sips 명령어 기능을 사용하기 위해 macOS가 필요","특정 이미지 형식(avif, webp, png, jpg, gif)만 지원","압축 이미지의 파일 크기 제한은 100KB"],"es":["Requiere macOS para la funcionalidad del comando sips","Limitado a formatos de imagen específicos (avif, webp, png, jpg, gif)","Límite de tamaño de archivo de 100KB para imágenes comprimidas"],"fr":["Nécessite macOS pour la fonctionnalité de la commande sips","Limité à des formats d''image spécifiques (avif, webp, png, jpg, gif)","Limite de taille de fichier de 100 Ko pour les images compressées"],"de":["Erfordert macOS für die Funktionalität des sips-Befehls","Begrenzt auf spezifische Bildformate (avif, webp, png, jpg, gif)","Dateigrößenbegrenzung von 100KB für komprimierte Bilder"],"pt":["Requer macOS para funcionalidade do comando sips","Limitado a formatos de imagem específicos (avif, webp, png, jpg, gif)","Limite de tamanho de arquivo de 100KB para imagens comprimidas"],"ru":["Требует macOS для функциональности команды sips","Ограничен конкретными форматами изображений (avif, webp, png, jpg, gif)","Ограничение размера файла 100 КБ для сжатых изображений"],"ar":["يتطلب نظام macOS للوظيفة命令 sips","محدود بتنسيقات الصور النوعية (avif و webp و png و jpg و gif)","حجم ملف محدود 100 كيلوبايت للصور المضغوطة"]},"version":3},"contentHash":"a82a3ca886de046173759b2652884690cc4c48a7ba2b7eab38c2aa7376cddef1","qualityScore":31}');
