INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TheOrcDev/8bitcn-ui/rerender-memo', 'rerender-memo', 'TheOrcDev', '8bitcn-ui', 'community', 'rerender-memo TheOrcDev 8bitcn-ui community rerender-memo是一个开源的、可访问的组件和代码分发平台，提供简单易用的开发体验 rerender-memoはオープンソースのアクセシブルコンポーネントとコード配布プラットフォームです。 rerender-memo는 오픈소스 및 접근성이 좋은 구성 요소 및 코드 배포 플랫폼입니다. Rerender-Memo es un conjunto de componentes accesibles y una plataforma de distribución de código de código abierto Rerender-Memo est un ensemble de composants accessibles et une plateforme de distribution de code ouvert Rerender-Memo ist ein Satz von barrierefreien Komponenten und einer Open-Source-Code-Verteilplattform Rerender-Memo é uma plataforma de código aberto que oferece componentes acessíveis e uma plataforma de distribuição de código Rerender-Memo - это открытая платформа, предлагающая доступные компоненты и платформу для распределения кода Rerender-Memo هي منصة mã aberta تقدم مركبات قابلة للوصول ومنصة لتوزيع الشفرة A set of retro-designed, accessible components and a code distribution platform. Open Source. Open Code. 如何使用rerender-memo 什么是rerender-memo rerender-memo安装 rerender-memo替代品 rerender-memo vs 其他工具 如何安装rerender-memo rerender-memo教程 rerender-memo文档 A set of retro-designed, accessible components and a code distribution platform. Open Source. Open Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('panaversity/agentfactory/quiz-generator', 'community', 'panaversity', 'agentfactory', 'panaversity/agentfactory', 'quiz-generator', 0, 0, 30, '2026-03-04T13:07:01.728Z', '2026-03-04T13:58:12.982Z', 'c7b96f9a2a1a24fde8642b8433ef261a46c6061fa2a2e786f55c468c19ec740b', '{"id":"panaversity/agentfactory/quiz-generator","name":"quiz-generator","description":{"zh":"使用Quiz Generator构建全天候运行的数字化全职员工。您的领域专业知识变成不间断工作的AI智能代理","ja":"Quiz Generatorを使用して24時間稼働するデジタルの従業員を構築。您的ドメインエキスパートISEは、眠らないAIエージェントになります","ko":"퀴즈 생성기를 사용하여 24시간 운영되는 디지털 직원을 구축하십시오.貴社の 도메인 전문 지식은 잠들지 않는 AI 에이전트가 됩니다","es":"Construye Agentes de IA digitales que trabajan las 24 horas con tu experiencia en ventas, legales, finanzas o atención médica","fr":"Construisez des Agents d''IA numériques qui travaillent 24h/24 avec votre expertise en vente, juridique, finance ou soins de santé","de":"Bauen Sie digitale künstliche Intelligenz-Agenten, die 24 Stunden am Tag mit Ihrer Expertise in Vertrieb, Recht, Finanzen oder Gesundheitswesen arbeiten","pt":"O quiz-generator permite criar soluções de IA Agentes que trabalham 24/7, tornando sua especialização em domínios como vendas, jurídico, finanças e saúde em uma solução autônoma","ru":"Генератор квизов позволяет создавать решения ИИ Агентов, которые работают 24/7, превращая ваш опыт в таких областях, как продажи, юридические услуги, финансы и здравоохранение, в автономное решение","ar":"مُولِّد اختبار يسمح بإنشاء حلول وكلاء الذكاء الاصطناعي التي تعمل 24/7، مما يجعل تخصصك في المجالات مثل المبيعات والقانون والمالية والرعاية الصحية في حل ذاتي التشغيل","en":"Build Digital FTEs that work 24/7. Your domain expertise—whether in sales, legal, finance, or healthcare—becomes an autonomous AI agent that never sleeps."},"seo":{"title":{"zh":"AI智能代理 - Quiz Generator","ja":"AIエージェント - Quiz Generator","ko":"AI 에이전트 - 퀴즈 생성기","