INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('liveloveapp/hashbrown/ideate', 'ideate', 'liveloveapp', 'hashbrown', 'community', 'ideate liveloveapp hashbrown community Hashbrown是一个用于构建运行在浏览器中的AI智能代理框架，支持Angular和React Hashbrownは、ブラウザで実行するAIエージェントを構築するためのフレームワークです。AngularとReactをサポートしています Hashbrown은 브라우저에서 실행되는 AI 에이전트를 구축하기 위한 프레임워크입니다. Angular 및 React를 지원합니다 Hashbrown es un framework para construir agentes de IA que se ejecutan en el navegador, diseñado para Angular y React Hashbrown est un framework pour construire des outils d''IA qui s''exécutent dans le navigateur, conçu pour Angular et React Hashbrown ist ein Framework zum Erstellen von KI-Agenten, die im Browser ausgeführt werden, entwickelt für Angular und React Hashbrown é um framework para construir agentes que executam no navegador, projetado para Angular e React. Ideate com Hashbrown Hashbrown - фреймворк для построения агентов, которые запускаются в браузере, предназначенный для Angular и React. Идеируйте с Hashbrown Hashbrown هو إطار عمل لإنشاء وكلاء يعملون في المتصفح، مصمم ل Angular و React. افترز مع Hashbrown Hashbrown is a framework for building agents that run the browser. Built for Angular and React. AI智能代理 Hashbrown框架 Angular和React支持 如何使用Hashbrown Hashbrown安装指南 Hashbrown与其他框架的比较 Hashbrown is a framework for building agents that run the browser. Built for Angular and React.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dickymoore/macs/loop', 'community', 'dickymoore', 'macs', 'dickymoore/macs', 'loop', 0, 0, 30, '2026-03-04T13:07:01.740Z', '2026-03-04T14:05:28.177Z', 'b81e76576038b22b43530b2542bb1de03a02a792ce9eef1107fb65b02b4ca80a', '{"id":"dickymoore/macs/loop","name":"loop","description":{"zh":"loop是一种多代理控制系统，使用tmux-based编排实现AI智能代理的高效控制","ja":"loopは、tmux-basedオーケストレーションを使用したAIエージェントのマルチエージェントコントロールシステムです","ko":"loop는 tmux-based 오케스트레이션을 사용한 AI 에이전트의 멀티 에이전트 제어 시스템입니다","es":"Loop es un sistema de control multiagente basado en tmux para agentes de codificación de IA, que permite una orquestación eficiente de tareas de desarrollo","fr":"Loop est un système de contrôle multi-agent basé sur tmux pour les agents de codage IA, qui permet une orchestration efficace des tâches de développement","de":"Loop ist ein Multi-Agenten-Steuerungssystem basierend auf tmux für IA-Coding-Agenten, das eine effiziente Orchestrierung von Entwicklungsaufgaben ermöglicht","pt":"O sistema de controle de agentes de IA baseado em tmux permite a orquestração de multiagentes para codificação de IA.","ru":"Система управления ИИ агентами на основе tmux позволяет оркестровать мультиагентов для кодирования ИИ.","ar":"نظام مراقبة وسيطرة العوامل الذكية القائم على tmux يسمح بأوركسترا للوكلاء المتعددين من أجل البرمجة الذكية.","en":"Multi Agent Control System - tmux-based orchestration for AI coding agents"},"seo":{"title":{"zh":"AI智能代理-loop多代理控制系统","ja":"AIエージェントのloop-マルチエージェントコントロールシステム","ko":"AI 에이전트 loop-멀티 에이전트 제어 시스템","es":"Herramientas de Agentes de IA: loop para control multiagente","fr":"Outils d''Agents IA: loop pour contrôle multi-agent","de":"AI-Agenten-Tools: loop für Multi-Agenten-Steuerung","pt":"Controle de Agentes de IA - Sistema de Orquestração basea...","ru":"Управление ИИ Агентами - Система оркестровки на основе tmux","ar":"مراقبة وسيطرة العوامل الذكية - نظام أوركسترا يستند إلى tmux","en":"loop"},"description":{"zh":"loop是一种多代理控制系统，使用tmux-based编排实现AI智能代理的高效控制","ja":"loopは、tmux-basedオーケストレーションを使用したAIエージェントのマルチエージェントコントロールシステムです","ko":"loop는 tmux-based 오케스트레이션을 사용한 AI 에이전트의 멀티 에이전트 제어 시스템입니다","es":"Loop es un sistema de control multiagente basado en tmux para agentes de codificación de IA, que permite una orquestación eficiente de tareas de desarrollo","fr":"Loop est un système de contrôle multi-agent basé sur tmux pour les agents de codage IA, qui permet une orchestration efficace des tâches de développement","de":"Loop ist ein Multi-Agenten-Steuerungssystem basierend auf tmux für IA-Coding-Agenten, das eine effiziente Orchestrierung von Entwicklungsaufgaben ermöglicht","pt":"O sistema de controle de agentes de IA baseado em tmux permite a orquestração de multiagentes para codificação de IA.","ru":"Система управления ИИ агентами на основе tmux позволяет оркестровать мультиагентов для кодирования ИИ.","ar":"نظام مراقبة وسيطرة العوامل الذكية القائم على tmux يسمح بأوركسترا للوكلاء المتعددين من أجل البرمجة الذكية.","en":"Multi Agent Control System - tmux-based orchestration for AI coding agents"},"definition":{"en":"Multi Agent Control System - tmux-based orchestration for AI coding agents"},"features":{"zh":["tmux-based编排","多代理控制","AI智能代理支持","高效控制和管理","灵活的配置和定制"],"ja":["tmux-basedオーケストレーション","マルチエージェントコントロール","AIエージェントのサポート","効率的な制御と管理","柔軟な設定とカスタマイズ"],"ko":["tmux-based 오케스트레이션","멀티 에이전트 제어","AI 에이전트 지원","효율적인 제어와 관리","유연한 설정과 커스터마이즈"],"es":["Control multiagente basado en tmux","Orquestación eficiente de tareas de desarrollo","Integración con herramientas de codificación de IA","Gestión de múltiples agentes de manera simultánea","Mejora de la productividad en el desarrollo de software"],"fr":["Contrôle multi-agent basé sur tmux","Orchestration efficace des tâches de développement","Intégration avec des outils de codage IA","Gestion de plusieurs agents de manière simultanée","Amélioration de la productivité dans le développement de logiciels"],"de":["Multi-Agenten-Steuerung basierend auf tmux","Effiziente Orchestrierung von Entwicklungsaufgaben","Integration mit IA-Coding-Tools","Verwaltung von mehreren Agenten gleichzeitig","Steigerung der Produktivität in der Software-Entwicklung"],"pt":["Controle de multiagentes","Orquestração baseada em tmux","Codificação de IA","Sistema de controle de agentes","Integração com ferramentas de desenvolvimento"],"ru":["Управление мультиагентами","Оркестровка на основе tmux","Кодирование ИИ","Система управления агентами","Интеграция с инструментами разработки"],"ar":["مراقبة وسيطرة العوامل المتعددة","نظام أوركسترا يستند إلى tmux","برمجة الذكاء الاصطناعي","نظام مراقبة وسيطرة العوامل","التكامل مع أدوات التطوير"]},"keywords":{"zh":["AI智能代理","多代理控制系统","tmux-based编排","如何使用loop","loop安装指南","loop替代品","loop和其他工具的比较"],"ja":["AIエージェント","マルチエージェントコントロールシステム","tmux-basedオーケストレーション","loopの使い方","loopのインストールガイド","loopの代替","loopと他のツールの比較"],"ko":["AI 에이전트","멀티 에이전트 제어 시스템","tmux-based 오케스트레이션","loop 사용 방법","loop 설치 가이드","loop의 대안","loop와 다른 도구의 비교"],"es":["herramientas de agentes de ia","loop para control multiagente","tmux para desarrollo de software","orquestación de tareas de desarrollo","mejora de la productividad en el desarrollo","alternativas a loop","loop vs otros herramientas de ia","instalación de loop","guía de configuración de loop"],"fr":["outils d''agents ia","loop pour contrôle multi-agent","tmux pour développement de logiciels","orchestration de tâches de développement","amélioration de la productivité dans le développement","alternatives à loop","loop vs autres outils d''ia","installation de loop","guide de configuration de loop"],"de":["ai-agenten-tools","loop für multi-agenten-steuerung","tmux für software-entwicklung","orchestrierung von entwicklungsaufgaben","steigerung der produktivität in der software-entwicklung","alternativen zu loop","loop vs andere ai-tools","installation von loop","konfigurationsanleitung für loop"],"pt":["como usar agentes de IA","o que é um agente de IA","alternativas para tmux","tmux vs screen","instalar tmux","guia de configuração de tmux"],"ru":["как использовать ИИ агенты","что такое ИИ агент","альтернативы для tmux","tmux vs screen","установить tmux","руководство по настройке tmux"],"ar":["كيفية استخدام العوامل الذكية","ما هو العامل الذكي","بديل لبرنامج tmux","تمكس مقابل الشاشة","تثبيت tmux","دليل إعداد tmux"]}},"owner":"dickymoore","repo":"macs","repoPath":"dickymoore/macs","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.740Z","topics":[],"category":"community","skillMd":{"name":"loop","description":"Keep the controller looping and progressing work without interruption.","bodyPreview":"# Loop Mode\n\n## Purpose\nTell the controller to keep working without interruption until blocked.\n\n## Usage\nLoad the prompt with: `/prompts:loop`\n\nThe prompt file lives at `.codex/prompts/loop.md`.\n\n## When to Use\n- Use when you want the controller to autonomously progress through tasks\n- Use when you don''t need to be interrupted for routine decisions\n- The controller will only break silence when completely blocked or complete","body":"# Loop Mode\n\n## Purpose\nTell the controller to keep working without interruption until blocked.\n\n## Usage\nLoad the prompt with: `/prompts:loop`\n\nThe prompt file lives at `.codex/prompts/loop.md`.\n\n## When to Use\n- Use when you want the controller to autonomously progress through tasks\n- Use when you don''t need to be interrupted for routine decisions\n- The controller will only break silence when completely blocked or complete\n"},"lastSynced":"2026-03-04T14:05:28.177Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Coding Agents requiring uninterrupted task progression and tmux-based orchestration.","zh":"适用于需要无中断任务进展和基于tmux的编排的自主编码代理。","ja":"tmuxベースのオーケストレーションを必要とする自律的なコーディングエージェントに最適です。","ko":"중단되지 않는 작업 진행과 tmux 기반의 오케스트레이션이 필요한 자율 코딩 에이전트에 적합합니다.","es":"Ideal para Agentes de Codificación Autónomos que requieren una progresión de tareas sin interrupciones y una orquestación basada en tmux.","fr":"Idéal pour les Agents de Codage Autonomes nécessitant une progression de tâches sans interruption et une orchestration basée sur tmux.","de":"Ideal für autonome Codierungsagenten, die eine unterbrechungsfreie Aufgabenverfolgung und eine tmux-basierte Orchestrierung erfordern.","pt":"Ideal para Agentes de Codificação Autônoma que requerem progressão de tarefa ininterrupta e orquestração baseada em tmux.","ru":"Идеально для автономных агентов кодирования, требующих непрерывного прогресса задач и оркестровки на основе tmux.","ar":"مثالي لعميل الترميز المستقل الذي يتطلب تقدم المهمة دون انقطاع وتنسيق قائم على tmux."},"recommendation":{"en":"Empowers agents to autonomously progress through tasks without interruptions, leveraging tmux-based orchestration and utilizing the `/prompts:loop` command for seamless execution, while only breaking silence when completely blocked or complete, as defined in the `.codex/prompts/loop.md` prompt file.","zh":"赋予代理自主地执行任务而不中断，利用tmux基于的编排和 `/prompts:loop` 命令进行无缝执行，只有当完全阻塞或完成时才会打破沉默，如 `.codex/prompts/loop.md` 提示文件中定义的。","ja":"エージェントが中断されずにタスクを実行できるようにし、tmuxベースのオーケストレーションと `/prompts:loop` コマンドを使用してシームレスに実行し、完全にブロックされたり完了したりした場合にのみサイレンスを破り、 `.codex/prompts/loop.md` のプロンプトファイルで定義されているようにします。","ko":"에이전트가 중단 없이 작업을 진행할 수 있도록 하며, tmux 기반의 오케스트레이션과 `/prompts:loop` 명령을 사용하여 무중단으로 실행하며, 완전히 블록되거나 완료될 때만沉默을 깨우며, `.codex/prompts/loop.md` 프롬프트 파일에서 정의한 대로 작동합니다.","es":"Habilita a los agentes a progresar de forma autónoma a través de las tareas sin interrupciones, aprovechando la orquestación basada en tmux y utilizando el comando `/prompts:loop` para una ejecución sin problemas, rompiendo el silencio solo cuando esté completamente bloqueado o completo, como se define en el archivo de prompt `.codex/prompts/loop.md`.","fr":"Permet aux agents de progresser de manière autonome à travers les tâches sans interruption, en exploitant l''orchestration basée sur tmux et en utilisant la commande `/prompts:loop` pour une exécution sans heurts, tout en rompant le silence uniquement lorsqu''il est complètement bloqué ou complet, comme défini dans le fichier de prompt `.codex/prompts/loop.md`.","de":"Ermöglicht es Agenten, Aufgaben ohne Unterbrechung autonom durchzuführen, indem sie die tmux-basierte Orchestrierung nutzen und den Befehl `/prompts:loop` für eine reibungslose Ausführung verwenden, während sie nur dann das Schweigen brechen, wenn sie vollständig blockiert oder abgeschlossen sind, wie in der Prompt-Datei `.codex/prompts/loop.md` definiert.","pt":"Habilita os agentes a progredir autonomamente nas tarefas sem interrupções, aproveitando a orquestração baseada em tmux e utilizando o comando `/prompts:loop` para execução contínua, apenas interrompendo o silêncio quando completamente bloqueado ou completo, conforme definido no arquivo de prompt `.codex/prompts/loop.md`.","ru":"Наделяет агентов возможностью автономного прогресса через задачи без прерываний, используя оркестровку на основе tmux и команду `/prompts:loop` для бесперебойного выполнения, при этом нарушая молчание только когда полностью заблокирован или завершен, как определено в файле подсказки `.codex/prompts/loop.md`.","ar":"يتمكن العملاء من المضي قدمًا بشكل مستقل في المهام دون انقطاع ، مستفيدين من التنسيق القائم على tmux واستخدام أمر `/prompts:loop` للتنفيذ السلس ، ويفسرون الصمت فقط عند الحظر الكامل أو الإكمال ، على النحو المحدد في ملف الإشارة `.codex/prompts/loop.md`."},"useCases":{"en":["Automating routine coding tasks","Progressing through complex coding workflows without interruption","Enabling autonomous decision-making for AI coding agents"],"zh":["自动化常规编码任务","无中断地进行复杂编码工作流","启用AI编码代理的自主决策"],"ja":["ルーチンなコーディングタスクの自動化","中断なく複雑なコーディングワークフローを実行","AIコーディングエージェントの自律的な意思決定を可能にする"],"ko":["루틴 코딩 작업 자동화","중단 없이 복잡한 코딩 워크플로우 진행","AI 코딩 에이전트의 자율적인 의사 결정 활성화"],"es":["Automatización de tareas de codificación rutinarias","Progresión a través de flujos de trabajo de codificación complejos sin interrupción","Habilitación de la toma de decisiones autónoma para agentes de codificación de IA"],"fr":["Automatisation des tâches de codage routinières","Progression à travers les flux de travail de codage complexes sans interruption","Activation de la prise de décision autonome pour les agents de codage de l''IA"],"de":["Automatisierung von Routinetätigkeiten bei der Codierung","Durchführung komplexer Codierungsworkflows ohne Unterbrechung","Ermöglichung autonomer Entscheidungsfindung für KI-Codierungsagenten"],"pt":["Automatizar tarefas de codificação rotineiras","Progredir por fluxos de trabalho de codificação complexos sem interrupção","Habilitar a tomada de decisões autônoma para agentes de codificação de IA"],"ru":["Автоматизировать рутинные задачи кодирования","Прогрессировать через сложные рабочие процессы кодирования без прерываний","Предоставить автономное принятие решений для агентов кодирования ИИ"],"ar":["تأتمة المهام البرمجية الروتينية","المضي في سلاسل مهام الترميز المعقدة دون انقطاع","تمكين اتخاذ القرارات المستقلة لعملاء الترميز الإصطناعي"]},"limitations":{"en":["Requires tmux-based Multi Agent Control System","Dependent on `.codex/prompts/loop.md` prompt file"],"zh":["需要tmux基于的多代理控制系统","依赖于 `.codex/prompts/loop.md` 提示文件"],"ja":["tmuxベースのマルチエージェントコントロールシステムが必要",".codex/prompts/loop.md のプロンプトファイルに依存"],"ko":["tmux 기반의 멀티 에이전트 제어 시스템 필요",".codex/prompts/loop.md 프롬프트 파일에 의존"],"es":["Requiere un Sistema de Control de Multiagente basado en tmux","Dependiente del archivo de prompt `.codex/prompts/loop.md`"],"fr":["Nécessite un Système de Contrôle Multiagent basé sur tmux","Dépendant du fichier de prompt `.codex/prompts/loop.md`"],"de":["Benötigt ein tmux-basiertes Multiagenten-Steuerungssystem","Abhängig von der Prompt-Datei `.codex/prompts/loop.md`"],"pt":["Requer Sistema de Controle de Múltiplos Agentes baseado em tmux","Dependente do arquivo de prompt `.codex/prompts/loop.md`"],"ru":["Требует системы управления несколькими агентами на основе tmux","Зависит от файла подсказки `.codex/prompts/loop.md`"],"ar":["يتطلب نظام التحكم في وكيل متعدد قائم على tmux","يعتمد على ملف الإشارة `.codex/prompts/loop.md`"]},"version":3},"contentHash":"b81e76576038b22b43530b2542bb1de03a02a792ce9eef1107fb65b02b4ca80a","qualityScore":30}');
