INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kevoreilly/capemon/capemon-developer', 'capemon-developer', 'kevoreilly', 'capemon', 'community', 'capemon-developer kevoreilly capemon community capemon-developer是CAPE的监控工具，用于提升开发效率和优化性能 capemon-developerはCAPEの監視ツールで、開発効率とパフォーマンスの最適化に役立ちます capemon-developer는 CAPE의 모니터링 툴로 개발 효율과 성능을 최적화하는 데 도움이 됩니다 capemon-developer es un monitor de CAPE que permite a los desarrolladores supervisar y optimizar sus proyectos. Es una herramienta de AI que ayuda a mejorar la eficiencia y la productividad. capemon-developer est un moniteur CAPE qui permet aux développeurs de surveiller et d''optimiser leurs projets. C''est un outil d''IA qui aide à améliorer l''efficacité et la productivité. capemon-developer ist ein CAPE-Monitor, der es Entwicklern ermöglicht, ihre Projekte zu überwachen und zu optimieren. Es ist ein KI-Tool, das dabei hilft, die Effizienz und Produktivität zu verbessern. O capemon-developer é uma ferramenta de monitoramento da CAPE projetada para desenvolvedores capemon-developer - это инструмент мониторинга CAPE, предназначенный для разработчиков أداة capemon-developer لمراقبة CAPE مصممة لمنشئي التطبيقات capemon: CAPE''s monitor AI智能代理工具 capemon-developer教程 如何使用capemon-developer capemon-developer替代品 capemon-developer安装 capemon-developer设置指南 capemon: CAPE''s monitor');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pegasus-isi/pegasus-workflow-toolkit/pegasus-wrapper', 'community', 'pegasus-isi', 'pegasus-workflow-toolkit', 'pegasus-isi/pegasus-workflow-toolkit', 'pegasus-wrapper', 0, 0, 30, '2026-03-04T13:07:01.928Z', '2026-03-04T15:06:02.638Z', 'a6bc044a5543161d2964c0fbaa156506eb58ea6e33008d55ae01db692e023f29', '{"id":"pegasus-isi/pegasus-workflow-toolkit/pegasus-wrapper","name":"pegasus-wrapper","description":{"zh":"Pegasus Wrapper是一个可重用工具包，用于创建Pegasus WMS工作流，基于Claude Code。它简化了开发流程，提高了效率","ja":"Pegasus Wrapperは、Claude Codeを使用してPegasus WMSワークフローを作成するための再利用可能なツールキットです。開発プロセスを簡素化し、効率を向上させます","ko":"Pegasus Wrapper는 Claude Code를 사용하여 Pegasus WMS 워크플ロー 생성을 위한 재사용 가능한 툴킷입니다. 개발 프로세스를 간소화하고 효율성을 향상시키는 데 도움을 줍니다","es":"Pegasus Wrapper es una herramienta reutilizable para crear flujos de trabajo de Pegasus WMS con Claude Code, mejorando la eficiencia y productividad","fr":"Pegasus Wrapper est un outil réutilisable pour créer des flux de travail Pegasus WMS avec Claude Code, améliorant l''efficacité et la productivité","de":"Pegasus Wrapper ist ein wiederverwendbares Tool zum Erstellen von Pegasus-WMS-Workflows mit Claude Code, um Effizienz und Produktivität zu steigern","pt":"A Pegasus Wrapper é uma ferramenta reutilizável para criar workflows de WMS com Claude Code, permitindo uma maior eficiência e produtividade","ru":"Pegasus Wrapper - повторно используемый инструмент для создания рабочих потоков WMS с Claude Code, обеспечивающий повышение эффективности и производительности","ar":"أداة Pegasus Wrapper هي أداة قابلة لإعادة الاستخدام لإنشاء سلاسل عمل WMS مع Claude Code، مما يسمح بزيادة الكفاءة والإنتاجية","en":"A reusable toolkit for creating Pegasus WMS workflows with Claude Code. "},"seo":{"title":{"zh":"Pegasus Wrapper AI工具：创建工作流的可重用工具包","ja":"Pegasus Wrapper AIエージェント：Claude Codeでワークフローを作成するための再利用可能な...","ko":"Pegasus Wrapper AI 에이전트: Claude Code로 워크플ロー 생성을 위한 재사용 가능...","es":"Herramientas de AI: Pegasus Wrapper para flujos de trabajo","fr":"Outils IA: Pegasus Wrapper pour flux de travail","de":"KI-Tools: Pegasus Wrapper für Workflows","pt":"Ferramenta Pegasus Wrapper: Crie Workflows com Claude Code","ru":"ИИ Агент Pegasus Wrapper: Создание Рабочих Потоков с Clau...","ar":"أداة Pegasus Wrapper: إنشاء سلاسل عمل مع Claude Code","en":"pegasus-wrapper"},"description":{"zh":"Pegasus Wrapper是一个可重用工具包，用于创建Pegasus WMS工作流，基于Claude Code。它简化了开发流程，提高了效率","ja":"Pegasus Wrapperは、Claude Codeを使用してPegasus WMSワークフローを作成するための再利用可能なツールキットです。開発プロセスを簡素化し、効率を向上させます","ko":"Pegasus Wrapper는 Claude Code를 사용하여 Pegasus WMS 워크플ロー 생성을 위한 재사용 가능한 툴킷입니다. 개발 프로세스를 간소화하고 효율성을 향상시키는 데 도움을 줍니다","es":"Pegasus Wrapper es una herramienta reutilizable para crear flujos de trabajo de Pegasus WMS con Claude Code, mejorando la eficiencia y productividad","fr":"Pegasus Wrapper est un outil réutilisable pour créer des flux de travail Pegasus WMS avec Claude Code, améliorant l''efficacité et la productivité","de":"Pegasus Wrapper ist ein wiederverwendbares Tool zum Erstellen von Pegasus-WMS-Workflows mit Claude Code, um Effizienz und Produktivität zu steigern","pt":"A Pegasus Wrapper é uma ferramenta reutilizável para criar workflows de WMS com Claude Code, permitindo uma maior eficiência e produtividade","ru":"Pegasus Wrapper - повторно используемый инструмент для создания рабочих потоков WMS с Claude Code, обеспечивающий повышение эффективности и производительности","ar":"أداة Pegasus Wrapper هي أداة قابلة لإعادة الاستخدام لإنشاء سلاسل عمل WMS مع Claude Code، مما يسمح بزيادة الكفاءة والإنتاجية","en":"A reusable toolkit for creating Pegasus WMS workflows with Claude Code. "},"definition":{"en":"A reusable toolkit for creating Pegasus WMS workflows with Claude Code. "},"features":{"zh":["基于Claude Code的Pegasus WMS工作流创建","可重用工具包，简化开发流程","提高效率，减少开发时间","支持多种开发环境","易于使用和集成"],"ja":["Claude Codeを使用したPegasus WMSワークフロー作成","再利用可能なツールキット、開発プロセスを簡素化","効率を向上させ、開発時間を短縮","多種の開発環境をサポート","簡単に使用および統合可能"],"ko":["Claude Code를 사용한 Pegasus WMS 워크플ロー 생성","재사용 가능한 툴킷, 개발 프로세스 간소화","효율성을 향상시키고 개발 시간을 단축","다양한 개발 환경 지원","쉽게 사용 및 통합 가능"],"es":["Creación de flujos de trabajo de Pegasus WMS","Integración con Claude Code","Herramienta de código abierto","Mejora de la eficiencia y productividad","Flexibilidad y personalización"],"fr":["Création de flux de travail Pegasus WMS","Intégration avec Claude Code","Outil open source","Amélioration de l''efficacité et de la productivité","Flexibilité et personnalisation"],"de":["Erstellung von Pegasus-WMS-Workflows","Integration mit Claude Code","Open-Source-Tool","Steigerung von Effizienz und Produktivität","Flexibilität und Anpassung"],"pt":["Criação de workflows de WMS personalizados","Integração com Claude Code","Ferramenta reutilizável","Melhoria da eficiência e produtividade","Suporte a múltiplos ambientes de desenvolvimento"],"ru":["Создание индивидуальных рабочих потоков WMS","Интеграция с Claude Code","Повторно используемый инструмент","Повышение эффективности и производительности","Поддержка нескольких сред разработки"],"ar":["إنشاء سلاسل عمل WMS مخصصة","التكامل مع Claude Code","أداة قابلة لإعادة الاستخدام","تحسين الكفاءة والإنتاجية","دعم بيئات متعددة للتنمية"]},"keywords":{"zh":["Pegasus Wrapper","AI工具","工作流创建","Claude Code","开发效率","如何使用Pegasus Wrapper","Pegasus Wrapper安装","Pegasus Wrapper设置指南"],"ja":["Pegasus Wrapper","AIエージェント","ワークフロー作成","Claude Code","開発効率","Pegasus Wrapperの使い方","Pegasus Wrapperのインストール","Pegasus Wrapperの設定ガイド"],"ko":["Pegasus Wrapper","AI 에이전트","워크플ロー 생성","Claude Code","개발 효율","Pegasus Wrapper 사용법","Pegasus Wrapper 설치","Pegasus Wrapper 설정 가이드"],"es":["herramientas de ai","pegasus wrapper","flujos de trabajo de pegasus wms","claud code","cómo usar pegasus wrapper","alternativas a pegasus wrapper","pegasus wrapper vs competidores","instalación de pegasus wrapper","guía de configuración de pegasus wrapper"],"fr":["outils ia","pegasus wrapper","flux de travail pegasus wms","claud code","comment utiliser pegasus wrapper","alternatives à pegasus wrapper","pegasus wrapper vs concurrents","installation de pegasus wrapper","guide de configuration de pegasus wrapper"],"de":["ki-tools","pegasus wrapper","pegasus-wms-workflows","claud code","wie man pegasus wrapper verwendet","alternativen zu pegasus wrapper","pegasus wrapper vs wettbewerber","installation von pegasus wrapper","einrichtungsanleitung für pegasus wrapper"],"pt":["como usar Pegasus Wrapper","o que é Pegasus Wrapper","Pegasus Wrapper alternativa","Pegasus Wrapper vs Claude Code","instalar Pegasus Wrapper","guia de configuração do Pegasus Wrapper"],"ru":["как использовать Pegasus Wrapper","что такое Pegasus Wrapper","альтернатива Pegasus Wrapper","Pegasus Wrapper vs Claude Code","установить Pegasus Wrapper","руководство по настройке Pegasus Wrapper"],"ar":["كيفية استخدام Pegasus Wrapper","ما هي أداة Pegasus Wrapper","بديل أداة Pegasus Wrapper","أداة Pegasus Wrapper مقابل Claude Code","تثبيت أداة Pegasus Wrapper","دليل إعداد أداة Pegasus Wrapper"]}},"owner":"pegasus-isi","repo":"pegasus-workflow-toolkit","repoPath":"pegasus-isi/pegasus-workflow-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.928Z","topics":[],"category":"community","skillMd":{"name":"pegasus-wrapper","description":"Generate a wrapper script for a single Pegasus pipeline step","bodyPreview":"# Pegasus Wrapper Script Generator\n\nYou are a Pegasus wrapper script generator. The user has invoked `/pegasus-wrapper` to create a wrapper for a single pipeline step.\n\n## Step 1: Read Reference Materials\n\n1. Read `Pegasus.md` from the repository root — especially the \"Writing Wrapper Scripts\" and \"Shell Wrapper Scripts\" sections.\n2. Read `pegasus-templates/wrapper_template.py` and `pegasus-templates/wrapper_template.sh` as starting points.\n\n## Step 2: Gather Requirements\n\nAsk the user (skip que","body":"# Pegasus Wrapper Script Generator\n\nYou are a Pegasus wrapper script generator. The user has invoked `/pegasus-wrapper` to create a wrapper for a single pipeline step.\n\n## Step 1: Read Reference Materials\n\n1. Read `Pegasus.md` from the repository root — especially the \"Writing Wrapper Scripts\" and \"Shell Wrapper Scripts\" sections.\n2. Read `pegasus-templates/wrapper_template.py` and `pegasus-templates/wrapper_template.sh` as starting points.\n\n## Step 2: Gather Requirements\n\nAsk the user (skip questions they''ve already answered):\n\n1. **Tool name**: What tool does this wrapper invoke? (e.g., `samtools sort`, `bwa mem`, a Python library, an API)\n2. **Inputs and outputs**: What files does it read and write? Include filenames or patterns.\n3. **Does the tool produce nested output?** If yes (e.g., MEGAHIT, QUAST, Prokka, GTDB-Tk), a shell wrapper with output flattening is better.\n4. **Python or shell?**\n   - Python (recommended for most cases): subprocess calls, API fetches, pure-Python analysis\n   - Shell (when needed): tools with nested output directories, headless display handling, simple tool chaining\n5. **Does this wrapper need to accept multiple input files?** (For fan-in/merge jobs, use `action=\"append\"` or `nargs=\"+\"`)\n6. **Does this wrapper call support files?** (R scripts, JARs, config files that Pegasus stages into the working directory)\n\n## Step 3: Select Reference Pattern\n\nBased on user answers, read the closest existing example:\n\n| Pattern | Reference |\n|---------|-----------|\n| Subprocess calling a CLI tool | `examples/wrapper_python_example.py` |\n| API fetch (requests) | `examples/workflow_generator_earthquake.py` (see fetch_earthquake_data pattern) |\n| Shell wrapper with output flattening | `examples/wrapper_shell_example.sh` |\n| ML training wrapper | `examples/workflow_generator_soilmoisture.py` (see train_model pattern) |\n| Fan-in merge (multiple inputs) | `examples/workflow_generator_airquality.py` (see merge pattern) |\n\nRead the selected reference before generating code.\n\n## Step 4: Generate the Wrapper\n\n### For Python wrappers:\n\nStart from `pegasus-templates/wrapper_template.py` and customize:\n\n1. **Docstring**: Describe what this step does\n2. **argparse arguments**: Must match what the `workflow_generator.py` will pass via `add_args()`\n3. **`os.makedirs`**: Create output subdirectories before writing (any path with `/`)\n4. **Tool invocation**: Use `subprocess.run()` for CLI tools, or call Python libraries directly\n5. **Exit code propagation**: `sys.exit(result.returncode)` after subprocess\n6. **Structured logging**: Use `logging` module with `logger.info()` for inputs, commands, and results\n7. **Output verification**: Check the output file exists before exiting\n\n### For shell wrappers:\n\nStart from `pegasus-templates/wrapper_template.sh` and customize:\n\n1. **`set -euo pipefail`**: Always include\n2. **Argument parsing**: `case` statement to extract named arguments\n3. **Tool execution**: Call the tool with parsed arguments\n4. **Output flattening**: Copy expected output files from nested directories to the working directory root\n5. **Headless handling** (if needed): `unset DISPLAY`, `xvfb-run` fallback\n\n### Critical Rules\n\n1. **Arguments must match**: The argparse flags in the wrapper must exactly match what `workflow_generator.py` passes in `add_args()`. Show the user both sides.\n2. **No directory scanning**: Never use `glob()`, `os.listdir()`, `list.files()`, or `find` to discover input files. Accept them explicitly via arguments.\n3. **Support files via `os.getcwd()`**: If the wrapper needs a support file (R script, JAR), find it with `os.path.join(os.getcwd(), \"filename\")` — NOT relative to `__file__`.\n4. **Create subdirectories**: Any output path containing `/` needs `os.makedirs(os.path.dirname(output), exist_ok=True)`.\n5. **Print the command**: Always log the command being run — this is essential for debugging via `pegasus-analyzer`.\n\n## Step 5: Show Integration\n\nAfter generating the wrapper, show the user the corresponding code needed in `workflow_generator.py`:\n\n1. **Transformation Catalog entry**: The `Transformation()` registration with correct `pfn`, `is_stageable`, memory, and cores\n2. **Job definition**: The `Job()` with `add_args()`, `add_inputs()`, `add_outputs()` that matches the wrapper''s argparse\n3. **Replica Catalog entry** (if the wrapper uses support files): `rc.add_replica()` for R scripts, JARs, etc.\n\nThis ensures the wrapper and workflow generator stay in sync.\n\n## Full Workflow Repositories\n\nFor complete wrapper scripts beyond the examples:\n- https://github.com/pegasus-isi/tnseq-workflow (Python wrappers for bioinformatics)\n- https://github.com/pegasus-isi/earthquake-workflow (API fetch wrappers)\n- https://github.com/pegasus-isi/mag-workflow (shell wrappers with output flattening)\n"},"lastSynced":"2026-03-04T15:06:02.638Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated workflow creation with Pegasus WMS and Claude Code integration.","zh":"适合需要使用Pegasus WMS和Claude Code集成自动化工作流创建的AI代理。","ja":"Pegasus WMSとClaude Codeの統合による自動ワークフローの作成を必要とするAIエージェントに適しています。","ko":"Pegasus WMS와 Claude Code 통합을 통해 자동 워크플로우 생성이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan la creación automática de flujos de trabajo con Pegasus WMS y la integración de Claude Code.","fr":"Parfait pour les agents IA nécessitant la création automatisée de flux de travail avec Pegasus WMS et l''intégration de Claude Code.","de":"Perfekt für KI-Agents, die die automatisierte Erstellung von Workflows mit Pegasus WMS und Claude Code-Integration benötigen.","pt":"Perfeito para Agentes de IA que precisam de criação de fluxo de trabalho automatizada com Pegasus WMS e integração com Claude Code.","ru":"Идеально подходит для агентов ИИ, которым требуется автоматизированное создание рабочих процессов с помощью Pegasus WMS и интеграции с Claude Code.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى إنشاء تدفق عمل آلي مع Pegasus WMS ودمج Claude Code."},"recommendation":{"en":"Empowers agents to generate reusable Pegasus wrapper scripts using Python, leveraging Claude Code for seamless workflow integration and shell wrapper scripts for flexible execution, all while utilizing pegasus-templates for standardized workflow development.","zh":"赋予代理使用Python生成可重用的Pegasus包装脚本的能力，利用Claude Code实现无缝的工作流集成，并使用shell包装脚本实现灵活的执行，同时利用pegasus-templates实现标准化的工作流开发。","ja":"Pythonを使用して再利用可能なPegasusラッパースクリプトを生成し、Claude Codeを利用してシームレスなワークフロー統合を実現し、shellラッパースクリプトを使用して柔軟な実行を実現し、pegasus-templatesを利用して標準化されたワークフローの開発を実現するエージェントをEmpowerします。","ko":"Python을 사용하여 재사용 가능한 Pegasus 래퍼 스크립트를 생성하고, Claude Code를 활용하여 무손실의 워크플로우 통합을 구현하며, 쉘 래퍼 스크립트를 사용하여 유연한 실행을 구현하며, pegasus-templates를 활용하여 표준화된 워크플로우 개발을 구현하는 에이전트를 강화합니다.","es":"Habilita a los agentes a generar scripts de wrapper de Pegasus reutilizables utilizando Python, aprovechando Claude Code para una integración de flujo de trabajo sin problemas y scripts de wrapper de shell para una ejecución flexible, todo mientras se utilizan pegasus-templates para el desarrollo de flujos de trabajo estandarizados.","fr":"Permet aux agents de générer des scripts de wrapper Pegasus réutilisables en utilisant Python, en exploitant Claude Code pour une intégration de flux de travail transparente et des scripts de wrapper shell pour une exécution flexible, le tout en utilisant pegasus-templates pour le développement de flux de travail standardisés.","de":"Ermöglicht es den Agents, wiederverwendbare Pegasus-Wrapper-Skripte mit Python zu generieren, indem Claude Code für eine nahtlose Workflow-Integration und Shell-Wrapper-Skripte für eine flexible Ausführung genutzt wird, und zwar unter Verwendung von pegasus-templates für die standardisierte Workflow-Entwicklung.","pt":"Habilita os agentes a gerar scripts de wrapper reutilizáveis do Pegasus usando Python, aproveitando o Claude Code para integração de fluxo de trabalho sem problemas e scripts de wrapper de shell para execução flexível, tudo isso utilizando pegasus-templates para desenvolvimento de fluxo de trabalho padronizado.","ru":"Наделяет агентов возможностью генерировать многократно используемые обертки Pegasus с помощью Python, используя Claude Code для бесперебойной интеграции рабочих процессов и оберток shell для гибкой реализации, все это при использовании pegasus-templates для стандартизированного развития рабочих процессов.","ar":"يمنح الوكلاء القدرة على توليد نصوص برمجية قابلة لإعادة الاستخدام من Pegasus باستخدام Python، مستفيدًا من Claude Code لدمج تدفق العمل دون مشاكل ونصوص برمجية غلاف Shell للتنفيذ المرن، كل ذلك باستخدام pegasus-templates لتطوير تدفق العمل المعياري."},"useCases":{"en":["Automating Pegasus WMS workflow creation","Generating wrapper scripts for pipeline steps","Integrating Claude Code with Pegasus workflows"],"zh":["自动化Pegasus WMS工作流创建","为管道步骤生成包装脚本","将Claude Code集成到Pegasus工作流中"],"ja":["Pegasus WMSワークフローの自動化","パイプラインのステップのラッパースクリプトの生成","Claude CodeをPegasusワークフローに統合する"],"ko":["Pegasus WMS 워크플로우 자동화","파이프라인 단계를 위한 래퍼 스크립트 생성","Claude Code를 Pegasus 워크플로우에 통합"],"es":["Automatización de la creación de flujos de trabajo de Pegasus WMS","Generación de scripts de wrapper para pasos de tuberías","Integración de Claude Code con flujos de trabajo de Pegasus"],"fr":["Automatisation de la création de flux de travail Pegasus WMS","Génération de scripts de wrapper pour les étapes de pipeline","Intégration de Claude Code avec les flux de travail Pegasus"],"de":["Automatisierung der Erstellung von Pegasus-WMS-Workflows","Generierung von Wrapper-Skripten für Pipeline-Schritte","Integration von Claude Code in Pegasus-Workflows"],"pt":["Automatizar a criação de fluxo de trabalho do Pegasus WMS","Gerar scripts de wrapper para etapas de pipeline","Integrar Claude Code com fluxos de trabalho do Pegasus"],"ru":["Автоматизировать создание рабочих процессов Pegasus WMS","Генерировать обертки для шагов конвейера","Интегрировать Claude Code с рабочими процессами Pegasus"],"ar":["توفير آلي لإنشاء تدفق عمل Pegasus WMS","توليد نصوص برمجية غلاف للخطوات المipeline","دمج Claude Code مع تدفقات العمل Pegasus"]},"limitations":{"en":["Requires access to Pegasus.md and pegasus-templates","Python environment necessary for script execution"],"zh":["需要访问Pegasus.md和pegasus-templates","需要Python环境来执行脚本"],"ja":["Pegasus.mdとpegasus-templatesへのアクセスが必要","スクリプトの実行にはPython環境が必要"],"ko":["Pegasus.md와 pegasus-templates에 대한 액세스가 필요","스크립트 실행을 위해 Python 환경이 필요"],"es":["Requiere acceso a Pegasus.md y pegasus-templates","Entorno de Python necesario para la ejecución de scripts"],"fr":["Nécessite l''accès à Pegasus.md et pegasus-templates","Environnement Python nécessaire pour l''exécution de scripts"],"de":["Erfordert den Zugriff auf Pegasus.md und pegasus-templates","Python-Umgebung erforderlich für die Skriptausführung"],"pt":["Requer acesso ao Pegasus.md e pegasus-templates","Ambiente Python necessário para execução de scripts"],"ru":["Требуется доступ к Pegasus.md и pegasus-templates","Необходимо окружение Python для выполнения скриптов"],"ar":["يتطلب الوصول إلى Pegasus.md و pegasus-templates","بيئة Python ضرورية لتشغيل البرامج النصية"]},"version":3},"contentHash":"a6bc044a5543161d2964c0fbaa156506eb58ea6e33008d55ae01db692e023f29","qualityScore":30}');
