INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SongYunSeop/oh-my-til/update-plugin', 'update-plugin', 'SongYunSeop', 'oh-my-til', 'community', 'update-plugin SongYunSeop oh-my-til community update-plugin是一个Obsidian插件，内嵌Claude Code终端、MCP服务器和TIL学习仪表盘，提供强大的开发工具 update-pluginは、Claude Codeターミナル、MCPサーバー、TIL学習ダッシュボードを内蔵したObsidianプラグインであり、強力な開発ツールを提供 update-plugin은 Claude Code 터미널, MCP 서버 및 TIL 학습 대시보드를 내장한 Obsidian 플러그인으로 강력한 개발 도구를 제공 El plugin de actualización para Obsidian integra una terminal de Claude Code, un servidor MCP y un panel de aprendizaje TIL Le plugin de mise à jour pour Obsidian intègre un terminal Claude Code, un serveur MCP et un tableau de bord d''apprentissage TIL Das Update-Plugin für Obsidian integriert ein Claude Code-Terminal, einen MCP-Server und ein TIL-Lern-Dashboard O update-plugin é uma ferramenta de atualização de plugin para Obsidian com Claude Code, MCP server e painel de aprendizado TIL. Ele oferece uma interface de terminal embutida para melhorar a produtividade Обновление плагина - это инструмент для обновления плагинов Obsidian с Claude Code, MCP сервером и панелью обучения TIL. Он предоставляет встроенную терминальную консоль для повышения производительности أداة تحديث البرنامج المساعد هي أداة لتحديث البرامج المساعدة في Obsidian مع شاشة طرفية Claude Code وخادم MCP ولوحة تعلم TIL. توفر واجهة طرفية مدمجة لتحسين الإنتاجية Obsidian plugin with embedded Claude Code terminal, MCP server, and TIL learning dashboard 如何使用update-plugin update-plugin安装指南 Obsidian插件开发 Claude Code终端使用 MCP服务器配置 TIL学习仪表盘设置 update-plugin与其他开发工具的比较 Obsidian plugin with embedded Claude Code terminal, MCP server, and TIL learning dashboard');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('inline-chat/inline/research', 'community', 'inline-chat', 'inline', 'inline-chat/inline', 'research', 642, 26, 30, '2026-02-25T16:07:21Z', '2026-02-26T08:28:27.388Z', '12a3befc365e999878a8fd77f28cef1248549d4171a21866dcb1745511db530c', '{"id":"inline-chat/inline/research","name":"research","description":{"zh":"Inline是一款快速、轻量、可扩展的协作聊天应用，支持无与伦比的协作带宽","ja":"Inlineは高速、軽量、スケーラブルなコラボレーションチャットアプリで、無与倫比のコラボレーションバンド幅を実現","ko":"Inline은 빠르고 가벼운 확장 가능한 협업 채팅 애플리케이션으로서 беспрецедент한 협업带宽을 지원","es":"Inline es una aplicación de chat de trabajo rápida, ligera, escalable y potente que permite una colaboración sin precedentes. La investigación es una de sus habilidades clave.","fr":"Inline est une application de chat de travail rapide, légère, évolutivité et puissante qui permet une collaboration sans précédent. La recherche est l''une de ses compétences clés.","de":"Inline ist eine schnelle, leichte, skalierbare und leistungsstarke Work-Chat-App, die eine beispiellose Zusammenarbeit ermöglicht. Die Recherche ist eine ihrer Schlüsselkompetenzen.","pt":"Inline é um aplicativo de bate-papo de trabalho rápido, leve e escalável que permite colaboração sem precedentes","ru":"Inline - это быстрое, легкое и масштабируемое приложение для обмена сообщениями в рабочей сети, обеспечивающее беспрецедентную широту сотрудничества","ar":"إنلاين هو تطبيق دردشة عمل سريع وخفيف ومرن يتيح تعاونا غير مسبوق","en":"Inline is a fast, lightweight, scalable, and powerful work chat app which enables unprecedented collaboration bandwidth."},"seo":{"title":{"zh":"AI智能研究工具 - Inline","ja":"AIエージェントによる研究 - Inline","ko":"AI 인텔리전트 연구 도구 - Inline","es":"Herramientas de investigación de Inteligencia Artificial","fr":"Outils de recherche d''Agents IA","de":"KI-Tools für Recherche","pt":"Ferramentas de Pesquisa de IA: Inline","ru":"ИИ Агенты: Исследование с Inli