INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elbwalker/walkerOS/walkeros-understanding-events', 'walkeros-understanding-events', 'elbwalker', 'walkerOS', 'community', 'walkeros-understanding-events elbwalker walkerOS community Walkeros 是一个开源的标签管理器，帮助开发者理解和处理事件 Walkeros はイベント理解と処理を支援するオープンソースのタグマネージャーです Walkeros는 이벤트 이해와 처리를 지원하는 오픈소스 태그 매니저입니다 walkeros-understanding-events es un gestor de etiquetas de código abierto para desarrolladores que simplifica la gestión de eventos walkeros-understanding-events est un gestionnaire de balises open-source pour les développeurs qui simplifie la gestion d''événements walkeros-understanding-events ist ein Open-Source-Tag-Manager für Entwickler, der die Verwaltung von Ereignissen vereinfacht O walkeros-understanding-events é um gerenciador de tags de código aberto para desenvolvedores, permitindo uma fácil implementação de eventos Walkeros-understanding-events - открытый менеджер тегов для разработчиков, позволяющий легко реализовывать события walkeros-understanding-events هو مدير علامات مفتوح المصدر للمطورين، يسمح بتطبيق_events بسهولة Open-source tag manager for developers 如何使用 Walkeros 什么是事件理解 Walkeros 替代品 Walkeros 与其他工具的比较 Walkeros 安装 Walkeros 设置指南 开源标签管理器 事件处理工具 Open-source tag manager for developers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/iOS Localization & Assets', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'iOS Localization & Assets', 0, 0, 30, '2026-02-20T04:13:19.581Z', '2026-03-01T07:23:48.925Z', '92928cc653b564577a07486f7d841dd1b550a10036ceb5dd8e209a4d0a7660b6', '{"id":"majiayu000/claude-skill-registry/iOS Localization & Assets","name":"iOS Localization & Assets","description":{"zh":"iOS 本地化与资产管理的标准，涵盖字符串目录、L10n和资产管理","ja":"iOS ローカライズとアセット管理の標準，文字列カタログ、L10n、资产管理を含む","ko":"iOS 로컬라이제이션 및 자산 관리의 표준，문자열 카탈로그、L10n、자산 관리를 포함","es":"Estándares para catálogos de cadenas, L10n y gestión de activos para desarrolladores de iOS","fr":"Normes pour les catalogues de chaînes, L10n et gestion d''actifs pour les développeurs iOS","de":"Standards für Zeichenfolgenkataloge, L10n und Asset-Verwaltung für iOS-Entwickler","pt":"Padrões para catálogos de strings, localização e gerenciamento de ativos para desenvolvedores iOS.","ru":"Стандарты для каталогов строк, локализации и управления активами для разработчиков iOS.","ar":"معايير الفهرس اللغوي و المحلية و إدارة الملفات لمنصة آيفون.","en":"Standards for String Catalogs, L10n, and Asset Management."},"seo":{"title":{"zh":"AI智能工具：iOS 本地化与资产管理","ja":"AIエージェント：iOS ローカライズとアセット管理","ko":"AI 에이전트: iOS 로컬라이제이션 및 자산 관리","es":"Herramientas de Localización iOS y Gestión de Activos","fr":"Outils de Localisation iOS et Gestion d''Actifs","de":"iOS Lokalisierungs- und Asset-Management-Tools","pt":"Ferramentas de AI: iOS Localização e Ativos","ru":"ИИ Агенты: Местоположение и Управление Активами iOS","ar":"أدوات الذكاء الاصطناعي: تحويل اللغة و إدارة الملفات للهات...","en":"iOS Localization & Assets"},"description":{"zh":"iOS 本地化与资产管理的标准，涵盖字符串目录、L10n和资产管理","ja":"iOS ローカライズとアセット管理の標準，文字列カタログ、L10n、资产管理を含む","ko":"iOS 로컬라이제이션 및 자산 관리의 표준，문자열 카탈로그、L10n、자산 관리를 포함","es":"Estándares para catálogos de cadenas, L10n y gestión de activos para desarrolladores de iOS","fr":"Normes pour les catalogues de chaînes, L10n et gestion d''actifs pour les développeurs iOS","de":"Standards für Zeichenfolgenkataloge, L10n und Asset-Verwaltung für iOS-Entwickler","pt":"Padrões para catálogos de strings, localização e gerenciamento de ativos para desenvolvedores iOS.","ru":"Стандарты для каталогов строк, локализации и управления активами для разработчиков iOS.","ar":"معايير الفهرس اللغوي و المحلية و إدارة الملفات لمنصة آيفون.","en":"Standards for String Catalogs, L10n, and Asset Management."},"definition":{"en":"Standards for String Catalogs, L10n, and Asset Management."},"features":{"zh":["字符串目录管理","L10n 和本地化支持","资产管理和优化","多语言支持","自动化本地化流程"],"ja":["文字列カタログ管理","L10n とローカライズサポート","アセット管理と最適化","多言語サポート","自動化ローカライズプロセス"],"ko":["문자열 카탈로그 관리","L10n 및 로컬라이제이션 지원","자산 관리 및 최적화","다국어 지원","자동화 로컬라이제이션 프로세스"],"es":["Estándares para catálogos de cadenas","Gestión de activos para aplicaciones móviles","Implementación de L10n","Integración con herramientas de desarrollo","Soporte para múltiples idiomas","Gestión de activos para iOS"],"fr":["Normes pour les catalogues de chaînes","Gestion d''actifs pour les applications mobiles","Mise en œuvre de L10n","Intégration avec des outils de développement","Prise en charge de plusieurs langues","Gestion d''actifs pour iOS"],"de":["Standards für Zeichenfolgenkataloge","Asset-Verwaltung für Mobile Apps","Implementierung von L10n","Integration mit Entwicklungstools","Unterstützung für mehrere Sprachen","Asset-Verwaltung für iOS"],"pt":["Padrões para catálogos de strings","Localização e internacionalização","Gerenciamento de ativos e recursos","Suporte a múltiplos idiomas","Integração com ferramentas de desenvolvimento"],"ru":["Стандарты для каталогов строк","Локализация и интернационализация","Управление активами и ресурсами","Поддержка нескольких языков","Интеграция с инструментами разработки"],"ar":["معايير الفهرس اللغوي","تحويل اللغة و التدويل","إدارة الملفات و الموارد","دعم اللغات المتعددة","التكامل مع أدوات التطوير"]},"keywords":{"zh":["iOS 本地化","资产管理","字符串目录","L10n","如何使用AI智能工具","iOS 本地化工具","资产管理最佳实践"],"ja":["iOS ローカライズ","アセット管理","文字列カタログ","L10n","AIエージェントの使用方法","iOS ローカライズツール","アセット管理ベストプラクティス"],"ko":["iOS 로컬라이제이션","자산 관리","문자열 카탈로그","L10n","AI 에이전트 사용 방법","iOS 로컬라이제이션 툴","자산 관리 베스트 프랙티스"],"es":["herramientas de localización de iOS","gestión de activos para aplicaciones móviles","cómo usar herramientas de localización","qué es la localización de iOS","alternativas a herramientas de localización","guía de instalación de herramientas de localización","herramientas de localización de iOS vs competidores"],"fr":["outils de localisation iOS","gestion d''actifs pour les applications mobiles","comment utiliser les outils de localisation","qu''est-ce que la localisation iOS","alternatives aux outils de localisation","guide d''installation des outils de localisation","outils de localisation iOS vs concurrents"],"de":["iOS-Lokalisierungs-Tools","Asset-Verwaltung für Mobile Apps","wie man Lokalisierungs-Tools verwendet","was ist iOS-Lokalisierung","Alternativen zu Lokalisierungs-Tools","Installationsanleitung für Lokalisierungs-Tools","iOS-Lokalisierungs-Tools vs Wettbewerber"],"pt":["como usar iOS Localização e Ativos","o que é localização em iOS","ferramentas de AI para desenvolvedores","iOS Localização e Ativos alternative","guia de instalação do iOS Localização e Ativos","configuração do iOS Localização e Ativos","desenvolvimento de aplicações iOS com localização"],"ru":["как использовать Местоположение и Управление Активами iOS","что такое локализация в iOS","ИИ Агенты для разработчиков","Местоположение и Управление Активами iOS alternative","руководство по установке Местоположение и Управление Активами iOS","настройка Местоположение и Управление Активами iOS","разработка приложений iOS с локализацией"],"ar":["كيفية استخدام تحويل اللغة و إدارة الملفات للهاتف المحمول","ما هي تحويل اللغة في آيفون","أدوات الذكاء الاصطناعي لل مطورين","تحويل اللغة و إدارة الملفات للهاتف المحمول alternative","دليل تثبيت تحويل اللغة و إدارة الملفات للهاتف المحمول","إعداد تحويل اللغة و إدارة الملفات للهاتف المحمول","تطوير تطبيقات آيفون مع تحويل اللغة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"iOS Localization & Assets","description":"Standards for String Catalogs, L10n, and Asset Management.","bodyPreview":"# iOS Localization & Assets Standards\n\n## **Priority: P1**\n\n## Implementation Guidelines\n\n### Localization (L10n)\n\n- **String Catalogs (.stringcatalog)**: Use for primary localization in Xcode 15+. It provides a visual editor and compile-time checks for missing translations.\n- **Native Implementation**: Use `String(localized: \"key\")` or `LocalizedStringResource`. Avoid manual `NSLocalizedString` where possible.\n- **Pluralization**: Use String Catalogs'' built-in pluralization support instead of c","body":"# iOS Localization & Assets Standards\n\n## **Priority: P1**\n\n## Implementation Guidelines\n\n### Localization (L10n)\n\n- **String Catalogs (.stringcatalog)**: Use for primary localization in Xcode 15+. It provides a visual editor and compile-time checks for missing translations.\n- **Native Implementation**: Use `String(localized: \"key\")` or `LocalizedStringResource`. Avoid manual `NSLocalizedString` where possible.\n- **Pluralization**: Use String Catalogs'' built-in pluralization support instead of complex code logic.\n- **Formatting**: Use `Formatted` API for dates, numbers, and currencies to respect the user''s locale.\n\n### Asset Management\n\n- **Asset Catalogs (.xcassets)**: Keep assets organized. Use folders with \"Provides Namespace\" enabled for large projects.\n- **SF Symbols**: Use for standard icons to ensure consistency and accessibility.\n- **Vector Assets**: Use PDF or SVG and enable \"Preserve Vector Data\" for resolution independence.\n\n### Best Practices\n\n- **Hardcoded Strings**: Never use hardcoded strings in UI. Every user-facing string must be localized.\n- **Base Bundle**: Ensure `Base` localization is complete before adding other languages.\n\n## Anti-Patterns\n\n- **Manual String Formatting**: `**No manual currency symbol concat**: Use NumberFormatter or .formatted(.currency).`\n- **Loose Asset Files**: `**No loose png/jpg files in repo**: Always use Asset Catalogs.`\n- **Untranslated Keys**: `**No placeholder strings**: Ensure 100% coverage in String Catalogs.`\n\n## References\n\n- [L10n & Asset Organization](references/implementation.md)\n"},"lastSynced":"2026-03-01T07:23:48.925Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Development Agents requiring streamlined iOS app localization and asset management.","zh":"非常适合需要简化iOS应用本地化和资产管理的移动开发代理。","ja":"iOSアプリのローカライズとアセット管理をストリームライン化する必要があるモバイル開発エージェントに最適です。","ko":"iOS 애플리케이션의 로컬라이제이션 및 자산 관리를 간소화해야 하는 모바일 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo móvil que requieren una localización y administración de activos de aplicaciones iOS optimizadas.","fr":"Parfait pour les agents de développement mobile nécessitant une localisation et une gestion d''actifs d''applications iOS rationalisées.","de":"Perfekt für Mobile Development Agents, die eine optimierte iOS-App-Localisierung und Asset-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Móvel que exigem localização de aplicativos iOS e gerenciamento de ativos simplificados.","ru":"Идеально подходит для агентов мобильной разработки, требующих упрощенной локализации приложений iOS и управления активами.","ar":"مثالي لعميل التطوير المحمول الذين يحتاجون إلى تخصيص تطبيق iOS وتحسين إدارة الموجودات."},"recommendation":{"en":"Empowers agents to efficiently manage iOS localization using String Catalogs (.stringcatalog) and Native Implementation with `String(localized: key)` or `LocalizedStringResource`, while also handling pluralization and asset optimization.","zh":"能够让代理高效地使用字符串目录（.stringcatalog）和原生实现`String(localized: key)`或`LocalizedStringResource`管理iOS本地化，同时还处理复数和资产优化。","ja":"エージェントがString Catalogs（.stringcatalog）とネイティブ実装の`String(localized: key)`または`LocalizedStringResource`を使用してiOSのローカライズを効率的に管理できるようにし、複数形とアセットの最適化も処理します。","ko":"에이전트가 문자열 카탈로그(.stringcatalog) 및 네이티브 구현의 `String(localized: key)` 또는 `LocalizedStringResource`를 사용하여 iOS 로컬라이제이션을 효율적으로 관리할 수 있도록 하며, 복수 및 자산 최적화를 처리합니다.","es":"Habilita a los agentes a gestionar eficientemente la localización de iOS utilizando Catálogos de Cadenas (.stringcatalog) y Implementación Nativa con `String(localized: key)` o `LocalizedStringResource`, mientras también maneja la pluralización y la optimización de activos.","fr":"Permet aux agents de gérer efficacement la localisation d''iOS en utilisant des catalogues de chaînes (.stringcatalog) et une implémentation native avec `String(localized: key)` ou `LocalizedStringResource`, tout en gérant également la pluralisation et l''optimisation des ressources.","de":"Ermächtigt die Agenten, die iOS-Localisierung effizient mithilfe von String-Katalogen (.stringcatalog) und Native Implementierung mit `String(localized: key)` oder `LocalizedStringResource` zu verwalten, während auch die Pluralisierung und Asset-Optimierung gehandhabt werden.","pt":"Habilita os agentes a gerenciar a localização do iOS de forma eficiente usando Catálogos de Strings (.stringcatalog) e Implementação Nativa com `String(localized: key)` ou `LocalizedStringResource`, além de lidar com a pluralização e a otimização de ativos.","ru":"Предоставляет агентам возможность эффективно управлять локализацией iOS с помощью Каталогов строк (.stringcatalog) и Родной реализации с `String(localized: key)` или `LocalizedStringResource`, а также обрабатывать формирование множественного числа и оптимизацию активов.","ar":"يمكن العميل من إدارة تخصيص iOS بفعالية باستخدام كتالوجات السلاسل (.stringcatalog) والتنفيذ الأصلي مع `String(localized: key)` أو `LocalizedStringResource` ، بالإضافة إلى التعامل مع التعددية وتحسين الموجودات."},"useCases":{"en":["Automating iOS app localization with String Catalogs","Generating localized assets for iOS apps","Debugging localization issues using Xcode 15+''s compile-time checks"],"zh":["使用字符串目录自动执行iOS应用本地化","为iOS应用生成本地化资产","使用Xcode 15+的编译时检查调试本地化问题"],"ja":["String Catalogsを使用してiOSアプリのローカライズを自動化する","iOSアプリのローカライズされたアセットを生成する","Xcode 15+のコンパイル時チェックを使用してローカライズの問題をデバッグする"],"ko":["문자열 카탈로그를 사용하여 iOS 애플리케이션의 로컬라이제이션을 자동화하는 것","iOS 애플리케이션의 로컬라이제이션된 자산을 생성하는 것","Xcode 15+의 컴파일 시간 체크를 사용하여 로컬라이제이션 문제를 디버깅하는 것"],"es":["Automatizar la localización de aplicaciones iOS con Catálogos de Cadenas","Generar activos localizados para aplicaciones iOS","Depurar problemas de localización utilizando las comprobaciones de tiempo de compilación de Xcode 15+"],"fr":["Automatiser la localisation d''applications iOS avec des catalogues de chaînes","Générer des ressources localisées pour les applications iOS","Déboguer les problèmes de localisation en utilisant les vérifications de temps de compilation de Xcode 15+"],"de":["Automatisieren der iOS-App-Localisierung mit String-Katalogen","Erzeugen lokalisierter Assets für iOS-Apps","Fehlerbehebung von Localisierungsproblemen unter Verwendung der Compile-Time-Checks von Xcode 15+"],"pt":["Automatizar a localização de aplicativos iOS com Catálogos de Strings","Gerar ativos localizados para aplicativos iOS","Depurar problemas de localização usando as verificações de tempo de compilação do Xcode 15+"],"ru":["Автоматизировать локализацию приложений iOS с помощью Каталогов строк","Генерировать локализованные активы для приложений iOS","Отлаживать проблемы локализации с помощью проверок во время компиляции Xcode 15+"],"ar":["أتمتة تخصيص تطبيق iOS باستخدام كتالوجات السلاسل","توليد الموجودات المُخصّصة لتطبيقات iOS","تصحيح أخطاء التخصيص باستخدام فحص زمن الترجمة من Xcode 15+"]},"limitations":{"en":["Requires Xcode 15+ for String Catalogs","Limited to iOS platform"],"zh":["需要Xcode 15+才能使用字符串目录","仅限iOS平台"],"ja":["String Catalogsを使用するにはXcode 15+が必要","iOSプラットフォームのみ"],"ko":["문자열 카탈로그를 사용하려면 Xcode 15+가 필요합니다.","iOS 플랫폼만 해당"],"es":["Requiere Xcode 15+ para Catálogos de Cadenas","Limitado a la plataforma iOS"],"fr":["Nécessite Xcode 15+ pour les catalogues de chaînes","Limité à la plate-forme iOS"],"de":["Benötigt Xcode 15+ für String-Kataloge","Begrenzt auf die iOS-Plattform"],"pt":["Exige Xcode 15+ para Catálogos de Strings","Limitado à plataforma iOS"],"ru":["Требует Xcode 15+ для Каталогов строк","Ограничен платформой iOS"],"ar":["يتطلب Xcode 15+ من أجل كتالوجات السلاسل","محدود منصة iOS"]},"version":3},"contentHash":"92928cc653b564577a07486f7d841dd1b550a10036ceb5dd8e209a4d0a7660b6","qualityScore":30}');
