INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('freepik-company/knowledge-agent/release', 'release', 'freepik-company', 'knowledge-agent', 'community', 'release freepik-company knowledge-agent community Release是一款AI知识管理代理，具有自动学习和语义搜索功能。支持多语言和自定义 Releaseは、自動学習とセマンティック検索機能を持つAI知識管理エージェントです。多言語対応とカスタマイズが可能 Release는 자동 학습 및 의미 검색 기능을 갖춘 AI 지식 관리 에이전트입니다. 다국어 및 커스터마이징 지원 El agente de gestión de conocimiento de IA ''release'' es una herramienta de búsqueda semántica y autoaprendizaje para capturar conocimiento institucional L''agent de gestion des connaissances IA ''release'' est un outil de recherche sémantique et d''auto-apprentissage pour capturer les connaissances institutionnelles Der KI-Wissensmanagement-Agent ''release'' ist ein Tool für semantische Suche und Auto-Lernen zur Erfassung von institutionellem Wissen O release é um agente de gerenciamento de conhecimento de IA com auto-aprendizado e busca semântica, integrado ao Slack ou API A2A, construído com Anthropic Claude, Go e pgvector Release - это ИИ агент управления знаниями с автономным обучением и семантическим поиском, интегрированный с Slack или API A2A, построенный на основе Anthropic Claude, Go и pgvector release هو وكلاء إدارة المعرفة بالذكاء الاصطناعي مع تعلم ذاتي وبحث دلالي، متوافق مع Slack أو API A2A، مبني على Anthropic Claude و Go و pgvector AI knowledge management agent with auto-learning and semantic search. Integrates with Slack or use A2A API for multi-agent systems. Built with Anthropic Claude, Go, and pgvector. Automatically captures institutional knowledge. Customizable, multilingual, production-ready. AI智能代理 自动化知识管理 语义搜索 Slack集成 A2A API 多语言支持 自定义功能 生产就绪 Anthropic Claude Go pgvector AI knowledge management agent with auto-learning and semantic search. Integrates with Slack or use A2A API for multi-agent systems. Built with Anthropic Claude, Go, and pgvector. Automatically captures institutional knowledge. Customizable, multilingual, production-ready.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BugRoger/2bd/_assistant-calendar', 'community', 'BugRoger', '2bd', 'BugRoger/2bd', '_assistant-calendar', 3, 0, 29, '2026-02-28T21:14:50Z', '2026-03-01T02:19:09.209Z', '2d6b98ac3b9b72abe0297e7f7a2e8ac34956e2ed3cdbd6accc121c71a018b85e', '{"id":"BugRoger/2bd/_assistant-calendar","name":"_assistant-calendar","description":{"zh":"第二大脑助手是一款个人知识和生产力系统，使用Claude Skills构建。它帮助开发者提高生产力和管理个人知识。","ja":"セカンドブレインデーモンは、Claude Skillsを使用して構築された个人知識と生産性システムです。開発者の生産性と個人知識管理を向上させます。","ko":"두번째 뇌 데몬은 Claude Skills를 사용하여 구축된 개인 지식 및 생산성 시스템입니다. 개발자의 생산성과 개인 지식 관리를 향상시킵니다.","es":"El asistente de calendario inteligente es un sistema de productividad personal basado en IA, construido con Claude Skills","fr":"L''assistant-calendrier intelligent est un système de productivité personnel basé sur l''IA, construit avec Claude Skills","de":"Der intelligente Kalender-Assistent ist ein persönliches Produktivitätssystem basierend auf KI, entwickelt mit Claude Skills","pt":"O Assistente de Calendário é um sistema de produtividade pessoal construído com Claude Skills, ajudando a gerenciar tarefas e eventos","ru":"Помощник Календаря - личная система продуктивности, построенная на основе Claude Skills, помогающая управлять задачами и событиями","ar":"مساعد التقويم هو نظام إنتاجية شخصي مبني على Claude Skills، يساعد في إدارة المهام والأحداث","en":"Second Brain Daemon - Personal knowledge and productivity system built with Claude Skills"},"seo":{"title":{"zh":"AI智能助理日历 - 第二大脑助手","ja":"AIエージェント カレンダー - セカンドブレインデーモン","ko":"AI 에이전트 달력 - 두번째 뇌 데몬","es":"Asistente de calendario inteligente - Herramientas de AI","fr":"Assistant-calendrier intelligent - Outils d''IA","de":"Intelligenter Kalender-Assistent - KI-Tools","pt":"Ferramentas de IA: Assistente de Calendário","ru":"ИИ Агенты: Помощник Календаря","ar":"أدوات الذكاء الاصطناعي: مساعد التقويم","en":