INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jbabin91/autocomplete-rs/beads-workflow', 'beads-workflow', 'jbabin91', 'autocomplete-rs', 'community', 'beads-workflow jbabin91 autocomplete-rs community beads-workflow是一个快速的智能Shell补全引擎，使用Rust编写。它能够提供快速的命令行补全建议，提高开发效率 beads-workflowは、Rustで書かれた高速なインテリジェントシェル補完エンジンです。高速なコマンドライン補完提案を提供し、開発効率を向上させます beads-workflow는 러스트로 작성된 빠른 지능형 쉘 자동완성 엔진입니다. 빠른 명령줄 자동완성 제안을 제공하여 개발 효율성을 향상합니다 Beads-workflow es un motor de autocompletado de shell rápido e inteligente escrito en Rust, ideal para desarrolladores que buscan mejorar su productividad Beads-workflow est un moteur de complétion de shell rapide et intelligent écrit en Rust, idéal pour les développeurs qui cherchent à améliorer leur productivité Beads-workflow ist ein schneller und intelligenter Shell-Vervollständigungs-Engine geschrieben in Rust, ideal für Entwickler, die ihre Produktivität steigern möchten O beads-workflow é um mecanismo de conclusão de shell rápido e inteligente escrito em Rust, projetado para melhorar a produtividade dos desenvolvedores beads-workflow - быстрый и интеллектуальный движок завершения shell на языке Rust, предназначенный для повышения производительности разработчиков beads-workflow هو محرك استكمال shell سريع ومحكم مكتوب بلغة الرست، مصمم لتحسين إنتاجية المطورين A fast, intelligent shell completion engine written in Rust 如何使用beads-workflow 什么是智能Shell补全 beads-workflow安装指南 beads-workflow替代品 beads-workflow vs 其他工具 beads-workflow设置教程 A fast, intelligent shell completion engine written in Rust');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nyaomaru/is-kit/prettier-format', 'community', 'nyaomaru', 'is-kit', 'nyaomaru/is-kit', 'prettier-format', 0, 0, 29, '2026-03-04T13:07:01.738Z', '2026-03-04T14:03:37.669Z', 'ba1303dc5ada8c9e822ada5dd44e00d7f833b6367d6f62b9cf2c38d0d51a7338', '{"id":"nyaomaru/is-kit/prettier-format","name":"prettier-format","description":{"zh":"prettier-format是一个轻量级、零依赖的TypeScript类型守卫构建工具，提供运行时安全、组合性和人体工程学","ja":"prettier-formatは、ランタイムセーフ、組み合わせ可能、エRGノミクスのTypeScriptのisFooスタイルタイプガードビルダーです","ko":"prettier-format는 런타임 안전, 조합 가능 및 인간 공학을 제공하는 TypeScript 타입 가드 빌더입니다","es":"Prettier es una herramienta de formato de código ligera y sin dependencias para TypeScript, que ofrece comprobaciones de tipo en tiempo de ejecución y composición","fr":"Prettier est un outil de formatage de code léger et sans dépendances pour TypeScript, offrant des vérifications de type à l''exécution et une composition","de":"Prettier ist ein leichtes und abhängigkeitsfreies Code-Formatierungstool für TypeScript, das Laufzeit-Typüberprüfungen und Zusammensetzung bietet","pt":"O prettier-format é uma ferramenta leve e segura para construir type guards em TypeScript, com funcionalidades de tempo de execução seguras e compostas.","ru":"Prettier-format - это легкий и безопасный инструмент для построения type guards в TypeScript, с функциями безопасного времени выполнения и композиции.","ar":"prettier-format هو أداة خفيفة وآمنة لإنشاء.type guards في TypeScript، مع ميزات زمن تشغيل آمن ومتكامل.","en":"Lightweight, zero-dependency toolkit for building `isFoo` style type guards in TypeScript. Runtime-safe 🛡️, composable 🧩, and ergonomic ✨. npm -> https://www.npmjs.com/package/is-kit"},"seo":{"title":{"zh":"AI工具prettier-format：TypeScript类型守卫构建工具","ja":"AIエージェントprettier-format：TypeScriptのisFooスタイルタイプガードビルダー","ko":"AI 에이전트 prettier-format: TypeScript 타입 가드 빌더","es":"Herr