INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('6/turbocop/triage', 'triage', '6', 'turbocop', 'community', 'triage 6 turbocop community rubocop ruby rust Triage是实验性RuboCop的Rust重写版本，旨在提高代码质量和性能 Triageは実験的なRuboCopのRustリライト版で、コードの品質とパフォーマンスを向上させることを目的としています Triage는 실험용 RuboCop의 Rust 재구성 버전으로 코드 품질과 성능을 향상시키는 것을 목표로 합니다 Triage es una versión experimental de RuboCop reescrita en Rust, diseñada para mejorar la eficiencia y la velocidad de desarrollo Triage est une version expérimentale de RuboCop réécrite en Rust, conçue pour améliorer l''efficacité et la vitesse de développement Triage ist eine experimentelle Version von RuboCop, die in Rust neu geschrieben wurde, um die Effizienz und die Entwicklungsgeschwindigkeit zu verbessern O Triage é uma reescrita experimental do RuboCop em Rust, visando melhorar a eficiência do código Ruby Triage - экспериментальная переписка RuboCop на Rust, направленная на повышение эффективности кода Ruby Triage هو إعادة كتابة تجريبية لRuboCop بلغة Rust، تهدف إلى تحسين كفاءة код Ruby Experimental RuboCop rewrite in Rust 如何使用Triage 什么是RuboCop Triage替代品 RuboCop vs Triage Triage安装 Triage设置指南 Ruby代码检查 Rust开发工具 Experimental RuboCop rewrite in Rust');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pjcau/esp32-emu-turbo/pcb-review', 'community', 'pjcau', 'esp32-emu-turbo', 'pjcau/esp32-emu-turbo', 'pcb-review', 1, 0, 28, '2026-03-01T21:46:46Z', '2026-03-02T02:06:54.416Z', 'e41fc2ee30110be6e1e9c754a739e01982d545b8923e9fa8a7bbc573a006a08e', '{"id":"pjcau/esp32-emu-turbo/pcb-review","name":"pcb-review","description":{"zh":"pcb-review是一款基于ESP32-S3的手持复古游戏机控制台，支持NES和SNES模拟","ja":"pcb-reviewは、ESP32-S3を使用したハンドヘルドレトロゲーム機コンソールで、NESとSNESのエミュレーションに対応","ko":"pcb-review는 ESP32-S3를 사용한 휴대용 레트로 게임 콘솔로 NES 및 SNES 에뮬레이션을 지원","es":"La herramienta de revisión de PCB es una consola de juegos retro portátil basada en ESP32-S3 para emulación de NES y SNES","fr":"L''outil d''examen de PCB est une console de jeux rétro portable basée sur ESP32-S3 pour l''émulation de NES et SNES","de":"Das Werkzeug zur Überprüfung von PCB ist eine tragbare Retro-Spielkonsole basierend auf ESP32-S3 für NES- und SNES-Emulation","pt":"A ferramenta de revisão de PCB é uma solução para desenvolvedores que desejam criar consoles de jogos retro portáteis com ESP32-S3 para emulação de NES e SNES","ru":"ИИ Агент для обзора печатных плат является решением для разработчиков, которые хотят создать портативные ретро-игровые консоли на основе ESP32-S3 для эмуляции NES и SNES","ar":"أداة مراجعة لوحات الدوائر المطبوعة هي حل لمطوري الذين يرغبون في إنشاء مشغلات ألعاب فيديو قديمة محمولة باستخدام ESP32-S3 لتعافي NES و SNES","en":"Handheld retro gaming console based on ESP32-S3 for NES and SNES emulation"},"seo":{"title":{"zh":"AI智能工具pcb-review：手持复古游戏机控制台","ja":"AIエージェントpcb-review：手持ちレトロゲーム機コンソール","ko":"AI 에이전트 pcb-review: 휴대용 레트로 게임 콘솔","es":"Herramientas de revisión de PCB para consolas de juegos r...","fr":"Outils d''examen de PCB pour consoles de jeux rétro","de":"Werkzeuge zur Überprüfung von PCB für Retro-Spielkonsolen","pt":"Ferramentas de Revisão de PCB 